    'расположен в одном из самых красивых и экологически чистых районов Подмосковья' => [
      'en' => 'is located in one of the most beautiful and environmentally clean areas of the Moscow Region',
      'ar' => 'يقع في واحدة من أجمل وأنظف مناطق ضواحي موسكو',
    ],
    'в Истринском районе, всего в 45 километрах от Москвы.' => [
      'en' => 'in the Istra district, just 45 kilometers from Moscow.',
      'ar' => 'في منطقة إسترا، على بعد 45 كيلومتراً فقط من موسكو.',
    ],
    'прекрасно подходит для того, чтобы уйти от городской суеты ради чистой природы и здорового образа жизни.' => [
      'en' => 'is perfect for leaving the city rush behind for clean nature and a healthy lifestyle.',
      'ar' => 'مثالي لترك صخب المدينة من أجل طبيعة نظيفة ونمط حياة صحي.',
    ],
    'создан в форме загородного жилого квартала. Земля, на которой он расположен, относится к категории земель населенных пунктов. У каждого дома есть свой почтовый адрес, а жители поселка могут воспользоваться правом прописки. Площадь поселка' => [
      'en' => 'is designed as a country residential quarter. The land is classified as settlement land. Each house has a postal address, and residents can register there. Village area',
      'ar' => 'مصمم كحي سكني ريفي. الأرض مصنفة كأراضي مستوطنات. لكل منزل عنوان بريدي ويمكن للسكان التسجيل فيه. مساحة القرية',
    ],
    '28 гектаров' => ['en' => '28 hectares', 'ar' => '28 هكتاراً'],
    'Откройте дверь и окунитесь в мир природы' => [
      'en' => 'Open the door and step into the world of nature',
      'ar' => 'افتح الباب وادخل عالم الطبيعة',
    ],
    'наблюдайте за дикой флорой и фауной, слушайте пение птиц, наслаждайтесь ароматами леса. Прекрасные виды на лес и водоем создают особую атмосферу и дарят эстетическое удовольствие. Дом, органично вписанный в природный ландшафт вашего участка станет настоящим оазисом спокойствия и гармонии.' => [
      'en' => 'watch wild flora and fauna, listen to birdsong, enjoy the forest scents. Views of the woods and water create a special atmosphere. A house that fits the landscape of your plot becomes a true oasis of calm.',
      'ar' => 'شاهد النباتات والحيوانات البرية، استمع لغناء الطيور واستمتع بعطور الغابة. إطلالات الغابة والماء تخلق أجواء خاصة. المنزل المنسجم مع الطبيعة يصبح واحة هدوء.',
    ],
    '45 мин от мкад на машине' => ['en' => '45 min from MKAD by car', 'ar' => '45 دقيقة من طريق موسكو بالسيارة'],
    'построить маршрут' => ['en' => 'get directions', 'ar' => 'إنشاء مسار'],
    'Команда архитекторов и дизайнеров разработает уникальный проект внутренней отделки дома и создаст уютный интерьер с учетом ваших пожеланий и современных трендов в загородной архитектуре' => [
      'en' => 'A team of architects and designers will create a unique interior project for your house, matching your wishes and current country-architecture trends',
      'ar' => 'سيضع فريق المعماريين والمصممين مشروعاً فريداً للتشطيب الداخلي وفق رغباتك واتجاهات العمارة الريفية',
    ],
    'готово помочь в реализации мечты' => ['en' => 'is ready to help make the dream real', 'ar' => 'جاهز للمساعدة في تحقيق الحلم'],
    'Добраться можно по МЦД-1 до железнодорожной станции г. Истра. Далее от станции регулярно курсирует маршрутный автобус' => [
      'en' => 'You can take MCD-1 to Istra railway station. A regular bus then runs from the station',
      'ar' => 'يمكن الوصول عبر MCD-1 إلى محطة قطار إسترا. ثم تنطلق حافلة منتظمة من المحطة',
    ],
    'до остановки «Духанино' => ['en' => 'to the Dukhanino stop', 'ar' => 'إلى محطة دوخانينو'],
    'Поворот на Духанино' => ['en' => 'Turn to Dukhanino', 'ar' => 'المنعطف إلى دوخانينو'],
    'расположенной в непосредственной близости от поселка.' => [
      'en' => 'located right next to the village.',
      'ar' => 'تقع بجوار القرية مباشرة.',
    ],
    'или на маршрутном такси. Время в пути 1 час 20 мин до ст. Истра' => [
      'en' => 'or by minibus. Travel time is 1 hour 20 minutes to Istra station',
      'ar' => 'أو بالميني باص. مدة الطريق ساعة و20 دقيقة إلى محطة إسترا',
    ],
    'Информация о коттеджном поселке Берег Песочной в Подмосковье' => [
      'en' => 'About the Bereg Pesochnoy cottage village in the Moscow Region',
      'ar' => 'عن قرية بيريج بيسوتشنايا في منطقة موسكو',
    ],
    'Информация о коттеджном поселке' => [
      'en' => 'About the cottage village',
      'ar' => 'عن قرية الكوتيدجات',
    ],
    'о коттеджном поселке' => ['en' => 'about the cottage village', 'ar' => 'عن قرية الكوتيدجات'],
    'в коттеджном поселке' => ['en' => 'in the cottage village', 'ar' => 'في قرية الكوتيدجات'],
    'в Подмосковье' => ['en' => 'in the Moscow Region', 'ar' => 'في منطقة موسكو'],
    'КП Берег Песочной - территория 28 га, 8 га парков, городские коммуникации на участке, первая очередь сдана и заселена, рядом водохранилище' => [
      'en' => 'Bereg Pesochnoy cottage village — 28 ha, 8 ha of parks, city utilities on every plot, the first stage is completed and occupied, a reservoir nearby',
      'ar' => 'قرية بيريج بيسوتشنايا — 28 هكتاراً، 8 هكتارات حدائق، خدمات المدينة على كل قطعة، المرحلة الأولى مكتملة ومأهولة، وخزان مياه قريب',
    ],
    'КП Bereg Pesochnoy - территория 28 ha, 8 ha парков, городские коммуникации на участке, первая очередь сдана и заселена, рядом водохранилище' => [
      'en' => 'Bereg Pesochnoy cottage village — 28 ha, 8 ha of parks, city utilities on every plot, the first stage is completed and occupied, a reservoir nearby',
      'ar' => 'قرية بيريج بيسوتشنايا — 28 هكتاراً، 8 هكتارات حدائق، خدمات المدينة على كل قطعة، المرحلة الأولى مكتملة ومأهولة، وخزان مياه قريب',
    ],
    'территория 28 ha, 8 ha парков, городские коммуникации на участке, первая очередь сдана и заселена, рядом водохранилище' => [
      'en' => '28 ha, 8 ha of parks, city utilities on every plot, the first stage is completed and occupied, a reservoir nearby',
      'ar' => '28 هكتاراً، 8 هكتارات حدائق، خدمات المدينة على كل قطعة، المرحلة الأولى مكتملة ومأهولة، وخزان مياه قريب',
    ],
    'Главная2' => ['en' => 'Cottage village', 'ar' => 'القرية'],
    'Home2' => ['en' => 'Cottage village', 'ar' => 'القرية'],
    'Дома в коттеджном поселке' => ['en' => 'Homes in the cottage village', 'ar' => 'منازل في القرية'],
    'Homes в коттеджном поселке' => ['en' => 'Homes in the cottage village', 'ar' => 'منازل في القرية'],
    'Жизнь за городом с городским комфортом' => [
      'en' => 'Country living with city comfort',
      'ar' => 'حياة ريفية براحة المدينة',
    ],
    'Жизнь за городом' => ['en' => 'Country living', 'ar' => 'الحياة الريفية'],
    'Как купить дом или участок в коттеджном поселке' => [
      'en' => 'How to buy a house or a plot in the cottage village',
      'ar' => 'كيف تشتري منزلاً أو أرضاً في القرية',
    ],
    'Как купить дом или участок' => [
      'en' => 'How to buy a house or a plot',
      'ar' => 'كيف تشتري منزلاً أو أرضاً',
    ],
    'Живописная природа для отдыха всей семьей' => [
      'en' => 'Scenic nature for a family holiday',
      'ar' => 'طبيعة خلابة لعطلة عائلية',
    ],
    'для отдыха всей семьей' => ['en' => 'for a family holiday', 'ar' => 'لعطلة عائلية'],
    '6 готовых домов' => ['en' => '6 ready homes', 'ar' => '6 منازل جاهزة'],
    'с участками' => ['en' => 'with plots', 'ar' => 'مع الأراضي'],
    'Большой выбор участков' => ['en' => 'A wide choice of plots', 'ar' => 'اختيار واسع من الأراضي'],
    'Строительство с подрядом' => ['en' => 'Turnkey construction', 'ar' => 'بناء بنظام تسليم المفتاح'],
    'Дома с подрядом' => ['en' => 'Homes with construction', 'ar' => 'منازل مع البناء'],
    'Homes с подрядом' => ['en' => 'Homes with construction', 'ar' => 'منازل مع البناء'],
    'Cтроящиеся дома' => ['en' => 'Homes under construction', 'ar' => 'منازل قيد الإنشاء'],
    'троящиеся дома' => ['en' => 'homes under construction', 'ar' => 'منازل قيد الإنشاء'],
    'с подрядом' => ['en' => 'with construction', 'ar' => 'مع البناء'],
    'Все дома возводятся по индивидуальным проектам в рамках единой архитектурной концепции по технологии БЭНПАН.' => [
      'en' => 'All houses are built to individual designs within a single architectural concept using BENPAN technology.',
      'ar' => 'تُبنى كل المنازل بتصاميم فردية ضمن مفهوم معماري موحّد بتقنية بنبان.',
    ],
    'За ландшафтом заботливо ухаживают садовники, чтобы прогулки были не только приятными, но и полезными для здоровья. Здесь можно гулять с детьми, устраивать семейные пикники и просто наслаждаться тишиной на скамейке в тени деревьев.' => [
      'en' => 'Gardeners carefully tend the landscape so walks are pleasant and good for your health. You can walk with children, have family picnics, or enjoy the quiet on a bench in the shade.',
      'ar' => 'يعتني البستانيون بالمناظر الطبيعية لتكون النزهات ممتعة ومفيدة. يمكنكم التنزّه مع الأطفال وتنظيم نزهات عائلية والاستمتاع بالهدوء على مقعد في الظل.',
    ],
    'Дышать свежим воздухом рядом с водоемом и лесом' => [
      'en' => 'Breathe fresh air by the water and the forest',
      'ar' => 'تنفّس هواءً نقياً بجانب الماء والغابة',
    ],
    'Уйти от городской суеты и наслаждаться загородной жизнью в окружении примыкающего к поселку леса, переходящего в парковую территорию, где высажено более 4000 деревьев.' => [
      'en' => 'Leave the city rush and enjoy country life surrounded by forest that turns into a park with more than 4,000 planted trees.',
      'ar' => 'اتركوا صخب المدينة واستمتعوا بالحياة الريفية وسط غابة تتحوّل إلى حديقة زُرع فيها أكثر من 4000 شجرة.',
    ],
    'Проводить больше времени у воды' => [
      'en' => 'Spend more time by the water',
      'ar' => 'اقضوا وقتاً أطول بجانب الماء',
    ],
    'Река Песочная протекающая около поселка — чистая, с пологими берегами и песчано-галечным дном, отличное место для занятий водными видами спорта или отдыха с удочкой.' => [
      'en' => 'The Pesochnaya river near the village is clean, with gentle banks and a sand-and-pebble bed — a great place for water sports or fishing.',
      'ar' => 'نهر بيسوتشنايا قرب القرية نظيف بضفاف لطيفة وقاع رملي حصوي — مكان ممتاز للرياضات المائية أو الصيد.',
    ],
    'Река Песочная протекающая около поселка — чистая, с пологими берегами и песчано-галечным дном, отличное moто для занятий водными видами спорта или отдыха с удочкой.' => [
      'en' => 'The Pesochnaya river near the village is clean, with gentle banks and a sand-and-pebble bed — a great place for water sports or fishing.',
      'ar' => 'نهر بيسوتشنايا قرب القرية نظيف بضفاف لطيفة وقاع رملي حصوي — مكان ممتاز للرياضات المائية أو الصيد.',
    ],
    'Жить with city comfort' => ['en' => 'Live with city comfort', 'ar' => 'عش براحة المدينة'],
    'В “Берег Песочной” есть все коммуникации для комфортного проживания в загородном доме. Жителям доступна инфраструктура города Истра расположенного в 10 минутах езды от поселка.' => [
      'en' => 'Bereg Pesochnoy has all utilities for comfortable country living. Residents can use the infrastructure of Istra, a 10-minute drive away.',
      'ar' => 'في بيريج بيسوتشنايا كل المرافق لحياة ريفية مريحة. تتوفر للسكان بنية إسترا على بعد 10 دقائق بالسيارة.',
    ],
    'В “Bereg Pesochnoy” есть все коммуникации для комфортного проживания в загородном доме. Жителям доступна инфраструктура города Истра расположенного в 10 минутах езды от поселка.' => [
      'en' => 'Bereg Pesochnoy has all utilities for comfortable country living. Residents can use the infrastructure of Istra, a 10-minute drive away.',
      'ar' => 'في بيريج بيسوتشنايا كل المرافق لحياة ريفية مريحة. تتوفر للسكان بنية إسترا على بعد 10 دقائق بالسيارة.',
    ],
    'Растить детей в окружении природы' => [
      'en' => 'Raise children surrounded by nature',
      'ar' => 'ربّوا الأطفال وسط الطبيعة',
    ],
    'На территории жилого комплекса есть детские площадки, скоро появится игровая комната, в 10 минутах от поселка находятся поликлиника, детские сады и школы.' => [
      'en' => 'There are playgrounds on the estate, a playroom is coming soon, and a clinic, kindergartens and schools are a 10-minute drive away.',
      'ar' => 'في المجمّع ملاعب أطفال، وستُفتتح غرفة ألعاب قريباً، وعلى بعد 10 دقائق عيادة ورياض أطفال ومدارس.',
    ],
    'Заботиться о здоровье и быть в форме' => [
      'en' => 'Take care of your health and stay in shape',
      'ar' => 'اعتنوا بصحتكم وابقوا في لياقة',
    ],
    'Площадки для активного отдыха и занятий спортом - открытый теннисный корт, футбольная и волейбольная площадки, гимнастические тренажеры (воркаут), позволят всегда быть в форме.' => [
      'en' => 'Sports areas — an open tennis court, football and volleyball pitches, outdoor workout machines — help you stay in shape.',
      'ar' => 'مناطق رياضية — ملعب تنس مكشوف وملاعب كرة قدم وطائرة وأجهزة تمارين — تساعدكم على البقاء في لياقة.',
    ],
    'Медицинские учреждения в 10 минутах езды на автомобиле' => [
      'en' => 'Medical facilities a 10-minute drive away',
      'ar' => 'مرافق طبية على بعد 10 دقائق بالسيارة',
    ],
    'Рядом детские сады, школы и досуговые центры' => [
      'en' => 'Kindergartens, schools and leisure centers nearby',
      'ar' => 'رياض أطفال ومدارس ومراكز ترفيه قريبة',
    ],
    'В поселке есть все коммуникации для комфортной жизни' => [
      'en' => 'The village has all utilities for a comfortable life',
      'ar' => 'في القرية كل المرافق لحياة مريحة',
    ],
    'Поселок «Берег Песочной» получил свое название от чистой реки Песочная, протекающей вдоль его южного края. Река подходит для купания и рыбалки. Поселок граничит с благоустроенным парком, в котором есть живописное озеро, беговые и велосипедные дорожки, беседки и площадка для выгула собак. У жителей есть собственный выход в парк. В поселке высажено более 4000 деревьев, и их количество ежегодно растет благодаря участию жителей.' => [
      'en' => 'The village takes its name from the clean Pesochnaya river along its southern edge. The river is good for swimming and fishing. The village borders a landscaped park with a scenic lake, running and cycling paths, gazebos and a dog area. Residents have their own access to the park. More than 4,000 trees have been planted, and the number grows every year with the help of residents.',
      'ar' => 'أخذت القرية اسمها من نهر بيسوتشنايا النظيف على حافتها الجنوبية. النهر مناسب للسباحة والصيد. تحدّ القرية حديقة مجهزة ببحيرة ومسارات للجري والدراجات وأكشاك ومنطقة للكلاب. للسكان مدخل خاص إلى الحديقة. زُرع أكثر من 4000 شجرة ويزداد عددها كل عام بمشاركة السكان.',
    ],
    ' получил свое название от чистой реки Песочная, протекающей вдоль его южного края. Река подходит для купания и рыбалки' => [
      'en' => ' takes its name from the clean Pesochnaya river along its southern edge. The river is good for swimming and fishing',
      'ar' => ' أخذت اسمها من نهر بيسوتشنايا النظيف على حافتها الجنوبية. النهر مناسب للسباحة والصيد',
    ],
    'граничит с благоустроенным парком, в котором есть живописное озеро, беговые и велосипедные дорожки, беседки и площадка для выгула собак. У жителей есть собственный выход в парк. В поселке высажено более 4000 деревьев, и их количество ежегодно растет благодаря участию жителей' => [
      'en' => 'borders a landscaped park with a scenic lake, running and cycling paths, gazebos and a dog area. Residents have their own access to the park. More than 4,000 trees have been planted, and the number grows every year with the help of residents',
      'ar' => 'تحدّ حديقة مجهزة ببحيرة ومسارات للجري والدراجات وأكشاك ومنطقة للكلاب. للسكان مدخل خاص إلى الحديقة. زُرع أكثر من 4000 شجرة ويزداد عددها كل عام بمشاركة السكان',
    ],
    'льготная ипотека и выгодная покупка' => [
      'en' => 'preferential mortgage and a good purchase',
      'ar' => 'تمويل ميسر وشراء بشروط جيدة',
    ],
    'и выгодная покупка' => ['en' => 'and a good purchase', 'ar' => 'وشراء بشروط جيدة'],
    'Наша компания является аккредитованным партнером (подрядчиком) в ДОМ.РФ, Росбанк, Сбербанк, ВТБ, Альфа, Газпромбанк по всем программам индивидуального жилого строительства (ИЖС). Окажем помощь в получении кредита на покупку готового или строящегося коттеджа, таунхауса или участка с подрядом. Работаем с любыми ипотечными программами, в том числе с эскроу счетами рассчитанными на строительство индивидуальных домов. Высокий процент одобрения заявок банками.' => [
      'en' => 'We are an accredited partner of DOM.RF, Rosbank, Sberbank, VTB, Alfa-Bank and Gazprombank for all individual housing programs. We help arrange a loan for a finished or under-construction cottage, townhouse or a plot with construction. We work with any mortgage programs, including escrow accounts for individual houses. Banks approve a high share of applications.',
      'ar' => 'نحن شريك معتمد لدى DOM.RF وروسبنك وسبيربنك وفي تي بي وألفا وغازبرومبنك لكل برامج البناء الفردي. نساعد في الحصول على تمويل لشراء كوتيدج جاهز أو قيد الإنشاء أو تاون هاوس أو أرض مع البناء. نعمل مع أي برامج تمويل بما فيها حسابات الضمان. نسبة موافقة البنوك مرتفعة.',
    ],
    'ИНВЕСТИЦИИ' => ['en' => 'INVESTMENTS', 'ar' => 'استثمار'],
    'ЗАЧТЕМ В СТОИМОСТЬ ВАШУ КВАРТИРУ' => [
