    'Примерьте роль владельца' => ['en' => 'Try on the owner’s role', 'ar' => 'جرّبوا دور المالك'],
    'Пишите в telegram' => ['en' => 'Write on Telegram', 'ar' => 'راسلونا على تيليغرام'],
    'Пишите в MAX' => ['en' => 'Write on MAX', 'ar' => 'راسلونا على MAX'],
