    'Уважаемые посетители 2,3,8,10 мая просмотр поселка осуществляется по предварительной записи. Записаться можно по телефону' => [
      'en' => 'Dear visitors, on 2, 3, 8 and 10 May the village can be viewed by appointment only. Book by phone',
