    'досуговый центр и детские площадки' => ['en' => 'leisure center and playgrounds', 'ar' => 'مركز ترفيه وملاعب أطفال'],
    'КП «Берег Песочной» — это не только дома и участки, но и продуманная инфраструктура для жизни за городом: коммуникации, охрана, парк, досуговые зоны и сервисы для повседневного комфорта.' => [
      'en' => 'Bereg Pesochnoy is not only homes and plots, but a thought-out infrastructure for country living: utilities, security, a park, leisure areas and everyday services.',
      'ar' => 'بيريج بيسوتشنايا ليست منازل وأراضياً فقط، بل بنية مدروسة للحياة الريفية: مرافق وحراسة وحديقة ومناطق ترفيه وخدمات يومية.',
    ],
    'Village «Bereg Pesochnoy» — это не только дома и участки, но и продуманная инфраструктура for living за городом: коммуникации, охрана, парк, досуговые зоны и сервисы для повседневного комфорта.' => [
      'en' => 'Bereg Pesochnoy is not only homes and plots, but a thought-out infrastructure for country living: utilities, security, a park, leisure areas and everyday services.',
      'ar' => 'بيريج بيسوتشنايا ليست منازل وأراضياً فقط، بل بنية مدروسة للحياة الريفية: مرافق وحراسة وحديقة ومناطق ترفيه وخدمات يومية.',
    ],
    'это не только дома и участки, но и продуманная инфраструктура for living за городом: коммуникации, охрана, парк, досуговые зоны и сервисы для повседневного комфорта.' => [
      'en' => 'is not only homes and plots, but a thought-out infrastructure for country living: utilities, security, a park, leisure areas and everyday services.',
      'ar' => 'ليست منازل وأراضياً فقط، بل بنية مدروسة للحياة الريفية: مرافق وحراسة وحديقة ومناطق ترفيه وخدمات يومية.',
    ],
    'Жизнь на природе с городским комфортом' => [
      'en' => 'Life in nature with city comfort',
      'ar' => 'حياة في الطبيعة براحة المدينة',
