    'Жизнь in nature with city comfort' => [
      'en' => 'Life in nature with city comfort',
      'ar' => 'حياة في الطبيعة براحة المدينة',
    ],
    'Инфраструктура «Берега Песочной» создана для постоянного проживания: закрытая охраняемая территория, городские коммуникации, собственный парк, досуговый центр и сервисы, которые помогают жить за городом без потери привычного уровня комфорта.' => [
      'en' => 'The infrastructure of Bereg Pesochnoy is built for year-round living: a gated secured territory, city utilities, its own park, a leisure center and services that let you live in the country without losing familiar comfort.',
      'ar' => 'بُنيت بنية بيريج بيسوتشنايا للسكن الدائم: منطقة مغلقة محروسة وخدمات المدينة وحديقة خاصة ومركز ترفيه وخدمات تتيح الحياة الريفية دون فقدان الراحة.',
    ],
    'Infrastructure «Берега Песочной» создана для постоянного проживания: закрытая охраняемая area, городские коммуникации, собственный парк, досуговый центр и сервисы, которые помогают жить за городом без потери привычного уровня комфорта.' => [
      'en' => 'The infrastructure of Bereg Pesochnoy is built for year-round living: a gated secured territory, city utilities, its own park, a leisure center and services that let you live in the country without losing familiar comfort.',
      'ar' => 'بُنيت بنية بيريج بيسوتشنايا للسكن الدائم: منطقة مغلقة محروسة وخدمات المدينة وحديقة خاصة ومركز ترفيه وخدمات تتيح الحياة الريفية دون فقدان الراحة.',
    ],
    'создана для постоянного проживания: закрытая охраняемая area, городские коммуникации, собственный парк, досуговый центр и сервисы, которые помогают жить за городом без потери привычного уровня комфорта.' => [
      'en' => 'is built for year-round living: a gated secured territory, city utilities, its own park, a leisure center and services that let you live in the country without losing familiar comfort.',
      'ar' => 'بُنيت للسكن الدائم: منطقة مغلقة محروسة وخدمات المدينة وحديقة خاصة ومركز ترفيه وخدمات تتيح الحياة الريفية دون فقدان الراحة.',
    ],
