    'mortgage от' => ['en' => 'mortgage from', 'ar' => 'تمويل من'],
    'Купить ТАУНХАУС' => ['en' => 'Buy a TOWNHOUSE', 'ar' => 'اشترِ تاون هاوس'],
    'по цене квартиры' => ['en' => 'at an apartment price', 'ar' => 'بسعر شقة'],
    'В коттеджном поселке Берег Песочной вы можете купить современный таунхаус с участком в одном из самых красивых и экологически чистых мест Подмосковья.  Мы предлагаем два проекта таунхаусов: Амстердам и Нью-Лондон. Амстердам – блокированный дом в классическом стиле со скатной крышей, состоящий из шести двух и трехуровневых квартир площадью от 140 до 200 м2. Нью-Лондон – жилой дом в современном стиле с плоской крышей, также состоящий из шести двух и трехуровневых квартир площадью от 120 до 200 м2.' => [
      'en' => 'In the Bereg Pesochnoy cottage village you can buy a modern townhouse with a plot in one of the greenest places in the Moscow Region. We offer two townhouse projects: Amsterdam and New London. Amsterdam is a classic pitched-roof terraced house of six two- and three-level homes from 140 to 200 m². New London is a contemporary flat-roof house of six two- and three-level homes from 120 to 200 m².',
      'ar' => 'في قرية بيريج بيسوتشنايا يمكنكم شراء تاون هاوس عصري مع أرض في واحدة من أجمل مناطق ضواحي موسكو. لدينا مشروعان: أمستردام ونيو لندن. أمستردام بيت متلاصق كلاسيكي بسقف مائل من ست شقق على مستويين أو ثلاثة بمساحة 140–200 م². نيو لندن بيت عصري بسقف مستوٍ من ست شقق على مستويين أو ثلاثة بمساحة 120–200 م².',
    ],
    'В коттеджном поселке Bereg Pesochnoy вы можете купить современный таунхаус с участком в одном из самых красивых и экологически чистых мест Подмосковья. Мы предлагаем два проекта таунхаусов: Amsterdam и Нью-Лондон. Amsterdam – блокированный дом в классическом стиле со скатной крышей, состоящий из шести двух и трехуровневых квартир площадью от 140 до 200 м2. Нью-Лондон – жилой дом в современном стиле с плоской крышей, также состоящий из шести двух и трехуровневых квартир площадью от 120 до 200 м2.' => [
      'en' => 'In the Bereg Pesochnoy cottage village you can buy a modern townhouse with a plot in one of the greenest places in the Moscow Region. We offer two townhouse projects: Amsterdam and New London. Amsterdam is a classic pitched-roof terraced house of six two- and three-level homes from 140 to 200 m². New London is a contemporary flat-roof house of six two- and three-level homes from 120 to 200 m².',
      'ar' => 'في قرية بيريج بيسوتشنايا يمكنكم شراء تاون هاوس عصري مع أرض في واحدة من أجمل مناطق ضواحي موسكو. لدينا مشروعان: أمستردام ونيو لندن. أمستردام بيت متلاصق كلاسيكي بسقف مائل من ست شقق على مستويين أو ثلاثة بمساحة 140–200 م². نيو لندن بيت عصري بسقف مستوٍ من ست شقق على مستويين أو ثلاثة بمساحة 120–200 م².',
    ],
    'вы можете купить современный таунхаус с участком в одном из самых красивых и экологически чистых мест Подмосковья. Мы предлагаем два проекта таунхаусов' => [
      'en' => 'you can buy a modern townhouse with a plot in one of the greenest places in the Moscow Region. We offer two townhouse projects',
      'ar' => 'يمكنكم شراء تاون هاوس عصري مع أرض في واحدة من أجمل مناطق ضواحي موسكو. لدينا مشروعان',
    ],
    'блокированный дом в классическом стиле со скатной крышей, состоящий из шести двух и трехуровневых квартир площадью от 140 до 200 м2.' => [
