    'online камера на объекте' => ['en' => 'live camera on site', 'ar' => 'كاميرا مباشرة في الموقع'],
    'Дом с участком у леса и воды, недалеко от Москвы, обладает большой привлекательностью для покупателей. Использование современных материалов, популярных планировок, высокое качество и скорость строительства делают инвестиции в загородные дома в коттеджных поселках выгодным вложением денежных средств, обеспечивая постоянный рост и приумножение вашего капитала.' => [
      'en' => 'A house with a plot by the forest and water, not far from Moscow, is highly attractive to buyers. Modern materials, popular layouts, high quality and construction speed make country-house investments in cottage villages a profitable way to grow your capital.',
      'ar' => 'منزل مع أرض بجانب الغابة والماء وقريب من موسكو جذاب للمشترين. المواد الحديثة والمخططات الشائعة والجودة وسرعة البناء تجعل الاستثمار في منازل القرى مربحاً وينمّي رأس المال.',
