    'АМСТЕРДАМ' => ['en' => 'AMSTERDAM', 'ar' => 'أمستردام'],
    'В коттеджном поселке Bereg Pesochnoy можно купить современный таунхаус с участком в красивом и экологически чистом районе Московской области' => [
