    'mortgage <span>от' => ['en' => 'mortgage <span>from', 'ar' => 'تمويل <span>من'],
    'Купить готовый или строящийся дом в КП Bereg Pesochnoy' => [
      'en' => 'Buy a ready or under-construction house in Bereg Pesochnoy',
      'ar' => 'اشترِ منزلاً جاهزاً أو قيد الإنشاء في بيريج بيسوتشنايا',
    ],
    'В поселке можно купить готовый дом с участком или построить по проекту из каталога. Все коттеджи в комплексе строятся из ЖБИ панелей по технологии БЭНПАН' => [
      'en' => 'In the village you can buy a ready house with a plot or build from a catalog project. All cottages are built from reinforced-concrete panels using BENPAN technology',
      'ar' => 'في القرية يمكن شراء منزل جاهز مع أرض أو البناء من مشروع الكتالوج. تُبنى كل الكوتيدجات من ألواح خرسانية بتقنية بنبان',
    ],
    'Частные резиденции в Московской области' => [
