    'в Московской области' => ['en' => 'in the Moscow Region', 'ar' => 'في منطقة موسكو'],
    'Эксклюзивное предложение в КП Берег Песочной – частные резиденции для ценителей комфорта, современной архитектуры и жизни на природе' => [
      'en' => 'An exclusive offer in Bereg Pesochnoy — private residences for those who value comfort, modern architecture and life in nature',
      'ar' => 'عرض حصري في بيريج بيسوتشنايا — إقامات خاصة لمن يقدّرون الراحة والعمارة الحديثة والحياة في الطبيعة',
    ],
    'Эксклюзивное предложение в КП Bereg Pesochnoy – частные residences для ценителей комфорта, современной архитектуры и жизни in nature' => [
      'en' => 'An exclusive offer in Bereg Pesochnoy — private residences for those who value comfort, modern architecture and life in nature',
      'ar' => 'عرض حصري في بيريج بيسوتشنايا — إقامات خاصة لمن يقدّرون الراحة والعمارة الحديثة والحياة في الطبيعة',
    ],
    'частные residences для ценителей комфорта, современной архитектуры и жизни in nature' => [
      'en' => 'private residences for those who value comfort, modern architecture and life in nature',
      'ar' => 'إقامات خاصة لمن يقدّرون الراحة والعمارة الحديثة والحياة في الطبيعة',
    ],
    '20 частных резиденций' => ['en' => '20 private residences', 'ar' => '20 إقامة خاصة'],
    'С ЖИВОПИСНЫМ ВИДОМ' => ['en' => 'WITH A SCENIC VIEW', 'ar' => 'بإطلالة خلابة'],
    'Архитектурное ателье БЭНПАН предлагает эксклюзивное предложение – концепты резиденций для строительства в КП «Берег Песочной», ценителям природы, комфорта и современной архитектуры. Коттеджный поселок бизнес-класса "Берег Песочной" предлагает 20 VIP-участков площадью от 10 до 20 соток, где живописный лес становится естественным продолжением вашего домовладения. Проживание в гармонии с природой, это не просто выбор дома, это инвестиция в по-настоящему качественную жизнь. Для беззаботного отдыха у воды резидентам поселка доступен эксклюзивный частный пляж.' => [
      'en' => 'The BENPAN architecture studio offers exclusive residence concepts for construction in Bereg Pesochnoy — for those who value nature, comfort and modern architecture. The business-class cottage village offers 20 VIP plots from 10 to 20 ares, where the scenic forest becomes a natural extension of your estate. Living in harmony with nature is not just a choice of house, it is an investment in a truly high-quality life. Residents also have access to an exclusive private beach.',
      'ar' => 'يقدّم مشغل بنبان المعماري مفاهيم إقامة حصرية للبناء في بيريج بيسوتشنايا لمحبي الطبيعة والراحة والعمارة الحديثة. توفّر القرية 20 قطعة VIP بمساحة 10–20 آرات حيث تصبح الغابة امتداداً طبيعياً للعقار. الحياة في انسجام مع الطبيعة استثمار في جودة الحياة. وللسكان شاطئ خاص حصري.',
    ],
    'предлагает эксклюзивное предложение – концепты резиденций для строительства в' => [
      'en' => 'offers an exclusive collection of residence concepts for construction in',
      'ar' => 'يقدّم مجموعة حصرية من مفاهيم الإقامة للبناء في',
    ],
    'концепты резиденций для строительства в' => [
      'en' => 'residence concepts for construction in',
      'ar' => 'مفاهيم إقامة للبناء في',
