      'en' => 'for those who value nature, comfort and modern architecture. The business-class cottage village',
      'ar' => 'لمن يقدّرون الطبيعة والراحة والعمارة الحديثة. قرية الكوتيدجات من فئة رجال الأعمال',
    ],
    'предлагает 20 VIP-участков площадью от 10 до 20 соток, где живописный лес становится естественным продолжением вашего домовладения. Проживание в гармонии с природой, это не просто выбор дома, это инвестиция в по-настоящему качественную жизнь. Для беззаботного отдыха у воды резидентам поселка доступен эксклюзивный частный пляж.' => [
      'en' => 'offers 20 VIP plots from 10 to 20 ares, where the scenic forest becomes a natural extension of your estate. Living in harmony with nature is not just a choice of house, it is an investment in a truly high-quality life. Residents also have access to an exclusive private beach.',
      'ar' => 'توفّر 20 قطعة VIP بمساحة 10–20 آرات حيث تصبح الغابة امتداداً طبيعياً للعقار. الحياة في انسجام مع الطبيعة استثمار في جودة الحياة. وللسكان شاطئ خاص حصري.',
    ],
