    'эксклюзивные проекты' => ['en' => 'exclusive projects', 'ar' => 'مشاريع حصرية'],
    'рады представить' => ['en' => 'we are pleased to present', 'ar' => 'يسعدنا أن نقدّم'],
    'КОНЦЕПТЫ РЕЗИДЕНЦИЙ' => ['en' => 'RESIDENCE CONCEPTS', 'ar' => 'مفاهيم الإقامات'],
    'Мы представляем вам уникальную коллекцию архитектурных концептов, которые могут быть реализованы в поселке. Это современные резиденции площадью от 300 кв.м., спроектированные с учетом передовых технологий, эргономики и эстетики. Эти дома еще не построены, но каждый из них- готовое решение, которое можно адаптировать под ваши пожелания.' => [
      'en' => 'We present a unique collection of architectural concepts that can be built in the village. These are modern residences from 300 m², designed with advanced technology, ergonomics and aesthetics. The houses are not built yet, but each is a ready solution that can be adapted to your wishes.',
      'ar' => 'نقدّم مجموعة فريدة من المفاهيم المعمارية التي يمكن تنفيذها في القرية. إقامات عصرية من 300 م² بتقنيات حديثة وراحة وجمال. المنازل لم تُبنَ بعد، لكن كل واحد حل جاهز يمكن تكييفه حسب رغبتكم.',
    ],
    'Мы представляем вам уникальную коллекцию архитектурных концептов, которые могут быть реализованы в village. Это современные residences площадью от 300 кв.м., спроектированные с учетом передовых технологий, эргономики и эстетики. Эти дома еще не построены, но каждый из них- готовое решение, которое можно адаптировать под ваши пожелания.' => [
      'en' => 'We present a unique collection of architectural concepts that can be built in the village. These are modern residences from 300 m², designed with advanced technology, ergonomics and aesthetics. The houses are not built yet, but each is a ready solution that can be adapted to your wishes.',
      'ar' => 'نقدّم مجموعة فريدة من المفاهيم المعمارية التي يمكن تنفيذها في القرية. إقامات عصرية من 300 م² بتقنيات حديثة وراحة وجمال. المنازل لم تُبنَ بعد، لكن كل واحد حل جاهز يمكن تكييفه حسب رغبتكم.',
    ],
    'которые могут быть реализованы в village. Это современные residences площадью от 300 кв.м., спроектированные с учетом передовых технологий, эргономики и эстетики. Эти дома еще не построены, но каждый из них- готовое решение, которое можно адаптировать под ваши пожелания.' => [
      'en' => 'that can be built in the village. These are modern residences from 300 m², designed with advanced technology, ergonomics and aesthetics. The houses are not built yet, but each is a ready solution that can be adapted to your wishes.',
      'ar' => 'يمكن تنفيذها في القرية. إقامات عصرية من 300 م² بتقنيات حديثة وراحة وجمال. المنازل لم تُبنَ بعد، لكن كل واحد حل جاهز يمكن تكييفه حسب رغبتكم.',
    ],
    'Получить презентацию' => ['en' => 'Get the presentation', 'ar' => 'احصل على العرض'],
    'РЕЗИДЕНЦИЯ' => ['en' => 'RESIDENCE', 'ar' => 'إقامة'],
