    'и рекой' => ['en' => 'and the river', 'ar' => 'والنهر'],
    'НЕОГРАНИЧЕННЫЕ ВОЗМОЖНОСТИ' => ['en' => 'UNLIMITED POSSIBILITIES', 'ar' => 'إمكانات بلا حدود'],
    'НЕОГРАНИЧЕННЫЕ' => ['en' => 'UNLIMITED', 'ar' => 'بلا حدود'],
    'ВОЗМОЖНОСТИ' => ['en' => 'POSSIBILITIES', 'ar' => 'إمكانات'],
    'с архитектурным ателье' => ['en' => 'with the architecture studio', 'ar' => 'مع المشغل المعماري'],
