    'хотите свой проект?' => ['en' => 'want your own project?', 'ar' => 'تريدون مشروعكم؟'],
    'Свяжитесь с нами, чтобы узнать подробнее о каждом проекте, посетить демонстрационные дома и обсудить детали строительства. Мы поможем вам сделать правильный выбор и воплотить ваши мечты в реальность.' => [
      'en' => 'Contact us to learn more about each project, visit show homes and discuss construction details. We will help you make the right choice and bring your plans to life.',
      'ar' => 'تواصلوا معنا لمعرفة المزيد عن كل مشروع وزيارة المنازل النموذجية ومناقشة البناء. سنساعدكم على الاختيار الصحيح وتحقيق أحلامكم.',
    ],
    'Свяжитесь с нами, чтобы learn more о каждом проекте, посетить демонстрационные дома и обсудить детали строительства. Мы поможем вам сделать правильный выбор и воплотить ваши мечты в реальность.' => [
      'en' => 'Contact us to learn more about each project, visit show homes and discuss construction details. We will help you make the right choice and bring your plans to life.',
      'ar' => 'تواصلوا معنا لمعرفة المزيد عن كل مشروع وزيارة المنازل النموذجية ومناقشة البناء. سنساعدكم على الاختيار الصحيح وتحقيق أحلامكم.',
    ],
    'о каждом проекте, посетить демонстрационные дома и обсудить детали строительства. Мы поможем вам сделать правильный выбор и воплотить ваши мечты в реальность.' => [
      'en' => 'about each project, visit show homes and discuss construction details. We will help you make the right choice and bring your plans to life.',
      'ar' => 'عن كل مشروع وزيارة المنازل النموذجية ومناقشة البناء. سنساعدكم على الاختيار الصحيح وتحقيق أحلامكم.',
    ],
    'УЗНАТЬ подробнее' => ['en' => 'LEARN more', 'ar' => 'اعرف المزيد'],
    'выгодные условия покупки' => ['en' => 'favorable purchase terms', 'ar' => 'شروط شراء ميسّرة'],
    'выгодные условия' => ['en' => 'favorable terms', 'ar' => 'شروط ميسّرة'],
    'покупки' => ['en' => 'of purchase', 'ar' => 'الشراء'],
    'Наша компания является аккредитованным партнером (подрядчиком) в ДОМ.РФ, Росбанк, Сбербанк, ВТБ, Альфа по всем программам индивидуального жилого строительства (ИЖС). Окажем помощь в получении кредита на покупку готового или строящегося коттеджа, таунхауса или участка с подрядом. Работаем с любыми ипотечными программами, рассчитанными на строительство индивидуальных домов. Высокий процент одобрения заявок банками.' => [
      'en' => 'We are an accredited partner of DOM.RF, Rosbank, Sberbank, VTB and Alfa-Bank for all individual housing programs. We help arrange a loan for a finished or under-construction cottage, townhouse or a plot with construction. We work with any mortgage programs for individual houses. Banks approve a high share of applications.',
      'ar' => 'نحن شريك معتمد لدى DOM.RF وروسبنك وسبيربنك وفي تي بي وألفا لكل برامج البناء الفردي. نساعد في تمويل كوتيدج جاهز أو قيد الإنشاء أو تاون هاوس أو أرض مع البناء. نعمل مع أي برامج تمويل للمنازل الفردية. نسبة موافقة البنوك مرتفعة.',
    ],
    'Окажем помощь в получении кредита на покупку готового или строящегося коттеджа, таунхауса или участка with construction. Работаем с любыми ипотечными программами, рассчитанными на строительство индивидуальных домов. Высокий процент одобрения заявок банками.' => [
      'en' => 'We help arrange a loan for a finished or under-construction cottage, townhouse or a plot with construction. We work with any mortgage programs for individual houses. Banks approve a high share of applications.',
      'ar' => 'نساعد في تمويل كوتيدج جاهز أو قيد الإنشاء أو تاون هاوس أو أرض مع البناء. نعمل مع أي برامج تمويل للمنازل الفردية. نسبة موافقة البنوك مرتفعة.',
    ],
    'Устройте уютные вечера у камина' => ['en' => 'Enjoy cozy evenings by the fireplace', 'ar' => 'أمضوا أمسيات دافئة عند المدفأة'],
    'Расслабляйтесь у собственного бассейна' => ['en' => 'Relax by your own pool', 'ar' => 'استرخوا عند مسبحكم'],
    'Прогуляйтесь по живописному лесу' => ['en' => 'Walk through the scenic forest', 'ar' => 'تنزّهوا في الغابة الخلابة'],
    'НАСЛАЖДЕНИЕ ЖИЗНЬЮ В ГАРМОНИИ С ПРИРОДОЙ' => [
      'en' => 'ENJOYING LIFE IN HARMONY WITH NATURE',
      'ar' => 'الاستمتاع بالحياة في انسجام مع الطبيعة',
    ],
    'НАСЛАЖДЕНИЕ' => ['en' => 'ENJOYING', 'ar' => 'الاستمتاع'],
    'ЖИЗНЬЮ' => ['en' => 'LIFE', 'ar' => 'الحياة'],
    'ЖИЗНЬЮ В ГАРМОНИИ' => ['en' => 'LIFE IN HARMONY', 'ar' => 'الحياة في انسجام'],
    'В ГАРМОНИИ' => ['en' => 'IN HARMONY', 'ar' => 'في انسجام'],
    'С ПРИРОДОЙ' => ['en' => 'WITH NATURE', 'ar' => 'مع الطبيعة'],
    'Пригласите друзей на Воскресное барбекю' => ['en' => 'Invite friends for a Sunday barbecue', 'ar' => 'ادعوا الأصدقاء لشواء يوم الأحد'],
    'Проведите романтический вечер на веранде' => ['en' => 'Spend a romantic evening on the terrace', 'ar' => 'أمضوا أمسية رومانسية على الشرفة'],
    'ХОРОШАЯ ТРАНСПОРТНАЯ ДОСТУПНОСТЬ' => ['en' => 'GOOD TRANSPORT ACCESS', 'ar' => 'وصول مواصلات جيد'],
    'ХОРОШАЯ ТРАНСПОРТНАЯ' => ['en' => 'GOOD TRANSPORT', 'ar' => 'مواصلات جيدة'],
    'ДОСТУПНОСТЬ' => ['en' => 'ACCESS', 'ar' => 'الوصول'],
    'Жилой комплекс «Берег Песочной» доступен с основных автомагистралей Подмосковья. В него легко проехать по Волоколамскому, Пятницкому, Новорижскому шоссе и ЦКАД. Время в пути на автомобиле от Москвы до жилого комплекса «Берег Песочной» занимает около 50 минут.' => [
      'en' => 'Bereg Pesochnoy is reachable from the main Moscow-Region highways. You can drive via Volokolamskoye, Pyatnitskoye, Novorizhskoye highways and the CKAD. The drive from Moscow takes about 50 minutes.',
      'ar' => 'يمكن الوصول إلى بيريج بيسوتشنايا من الطرق الرئيسية لضواحي موسكو عبر فولوكولامسكوي وبياتنيتسكي ونوفوريجسكوي والطريق الدائري. تستغرق الرحلة من موسكو نحو 50 دقيقة.',
    ],
    'доступен с основных автомагистралей Подмосковья. В него легко проехать по Волоколамскому, Пятницкому, Новорижскому шоссе и ЦКАД. Время в пути на автомобиле от Москвы до жилого комплекса' => [
      'en' => 'is reachable from the main Moscow-Region highways. You can drive via Volokolamskoye, Pyatnitskoye, Novorizhskoye highways and the CKAD. The drive from Moscow to the residential complex',
      'ar' => 'يمكن الوصول إليها من الطرق الرئيسية لضواحي موسكو عبر فولوكولامسكوي وبياتنيتسكي ونوفوريجسكوي والطريق الدائري. تستغرق الرحلة من موسكو إلى المجمّع',
    ],
    'занимает около 50 минут.' => ['en' => 'takes about 50 minutes.', 'ar' => 'تستغرق نحو 50 دقيقة.'],
    'От Рижского вокзала на электричке до г. Истра. Далее от железнодорожной станции маршрутным автобусом №30 до остановки Духанино/поворот на Духанино.' => [
      'en' => 'From Rizhsky railway station take a commuter train to Istra. Then bus 30 from the station to the Dukhanino / turn to Dukhanino stop.',
      'ar' => 'من محطة ريجسكي بالقطار إلى إسترا. ثم الحافلة 30 من المحطة إلى دوخانينو / منعطف دوخانينو.',
    ],
    'Лесная улица, 1, коттеджный посёлок Берег Песочной, городской округ Истра, Московская область' => [
      'en' => '1 Lesnaya Street, Bereg Pesochnoy cottage village, Istra urban district, Moscow Region',
      'ar' => 'شارع ليسنايا 1، قرية بيريج بيسوتشنايا، دائرة إسترا، منطقة موسكو',
    ],
    'коттеджный посёлок' => ['en' => 'cottage village', 'ar' => 'قرية الكوتيدجات'],
    '1 Lesnaya Street, коттеджный посёлок Bereg Pesochnoy, Istra urban district, Moscow Region' => [
      'en' => '1 Lesnaya Street, Bereg Pesochnoy cottage village, Istra urban district, Moscow Region',
      'ar' => 'شارع ليسنايا 1، قرية بيريج بيسوتشنايا، دائرة إسترا، منطقة موسكو',
    ],
    'Понтонный пляж для жителей поселка' => ['en' => 'Pontoon beach for village residents', 'ar' => 'شاطئ عائم لسكان القرية'],
    'Pontoon beach для жителей поселка' => ['en' => 'Pontoon beach for village residents', 'ar' => 'شاطئ عائم لسكان القرية'],
    'для жителей поселка' => ['en' => 'for village residents', 'ar' => 'لسكان القرية'],
    'Пространство отдыха на воде: шезлонги, кафе-бар, прокат лодок, прозрачные купольные лаунж-зоны и удобный выход к прогулочной набережной.' => [
      'en' => 'A leisure space on the water: sun loungers, a cafe-bar, boat rental, transparent dome lounges and easy access to the promenade.',
      'ar' => 'مساحة استجمام على الماء: كراسي استلقاء ومقهى وتأجير قوارب وصالات قببية ومدخل سهل إلى الممشى.',
    ],
    'Посмотреть схему' => ['en' => 'See the layout', 'ar' => 'عرض المخطط'],
    'протяженность основной платформы' => ['en' => 'length of the main platform', 'ar' => 'طول المنصة الرئيسية'],
    '4 зоны' => ['en' => '4 zones', 'ar' => '4 مناطق'],
    'отдых, кафе, прокат, прогулки' => ['en' => 'rest, cafe, rental, walks', 'ar' => 'راحة ومقهى وتأجير ونزهات'],
    'вид на воду, лес и парк' => ['en' => 'a view of the water, forest and park', 'ar' => 'إطلالة على الماء والغابة والحديقة'],
    'спокойный формат рядом с домом' => ['en' => 'a quiet format next to home', 'ar' => 'صيغة هادئة بجانب المنزل'],
    'Собственный пляжный клуб без выезда из поселка' => [
      'en' => 'Your own beach club without leaving the village',
      'ar' => 'نادي شاطئ خاص دون مغادرة القرية',
    ],
    'Понтонный пляж усиливает главное преимущество «Берега Песочной» — жизнь рядом с водой. Это не просто настил у берега, а полноценная точка притяжения для прогулок, встреч, летнего отдыха и семейных выходных.' => [
      'en' => 'The pontoon beach adds to Bereg Pesochnoy’s main advantage — life by the water. It is not just a deck on the shore, but a place for walks, meetings, summer rest and family weekends.',
      'ar' => 'الشاطئ العائم يعزّز ميزة بيريج بيسوتشنايا — الحياة بجانب الماء. ليس مجرد رصيف، بل مكان للنزهات واللقاءات وراحة الصيف وعطل العائلة.',
    ],
    'Pontoon beach усиливает главное преимущество «Bereg Pesochnoy» — жизнь рядом с водой. Это не просто настил у берега, а полноценная точка притяжения для прогулок, встреч, летнего отдыха и семейных выходных.' => [
      'en' => 'The pontoon beach adds to Bereg Pesochnoy’s main advantage — life by the water. It is not just a deck on the shore, but a place for walks, meetings, summer rest and family weekends.',
      'ar' => 'الشاطئ العائم يعزّز ميزة بيريج بيسوتشنايا — الحياة بجانب الماء. ليس مجرد رصيف، بل مكان للنزهات واللقاءات وراحة الصيف وعطل العائلة.',
    ],
    'усиливает главное преимущество' => ['en' => 'adds to the main advantage of', 'ar' => 'يعزّز الميزة الرئيسية لـ'],
    'Это не просто настил у берега, а полноценная точка притяжения для прогулок, встреч, летнего отдыха и семейных выходных.' => [
      'en' => 'It is not just a deck on the shore, but a place for walks, meetings, summer rest and family weekends.',
      'ar' => 'ليس مجرد رصيف، بل مكان للنزهات واللقاءات وراحة الصيف وعطل العائلة.',
    ],
    'Комфортный отдых' => ['en' => 'Comfortable rest', 'ar' => 'راحة مريحة'],
    'Комфортный отдых на понтоне' => ['en' => 'Comfortable rest on the pontoon', 'ar' => 'راحة مريحة على الرصيف'],
    'Каштановые, липовые и кленовые аллеи, фруктовый сад с яблонями и вишней, прогулочная зона, пруд и живой уголок.' => [
      'en' => 'Chestnut, linden and maple alleys, an orchard with apple and cherry trees, a walking area, a pond and a wildlife corner.',
      'ar' => 'أزقة كستناء وزيزفون وأسفندان، وبستان تفاح وكرز، ومنطقة تنزه وبركة وركن حي.',
    ],
    'Кафе и бар на воде' => ['en' => 'Cafe and bar on the water', 'ar' => 'مقهى وبار على الماء'],
    'Отдохните после рабочего дня с чашкой ароматного травяного чая в кафе над гладью озера, насладитесь закатом солнца.' => [
      'en' => 'Unwind after work with a cup of herbal tea in the cafe over the lake and enjoy the sunset.',
      'ar' => 'استرخوا بعد العمل بكوب شاي أعشاب في المقهى فوق البحيرة واستمتعوا بالغروب.',
    ],
    'над гладью озера' => ['en' => 'over the lake', 'ar' => 'فوق البحيرة'],
    'над гладью lake' => ['en' => 'over the lake', 'ar' => 'فوق البحيرة'],
    'Активности у воды' => ['en' => 'Activities by the water', 'ar' => 'أنشطة بجانب الماء'],
    'Причал для лодок и катамаранов. Совершайте водные прогулки, проводите больше времени на свежем воздухе.' => [
      'en' => 'A pier for boats and catamarans. Take water trips and spend more time outdoors.',
      'ar' => 'رصيف للقوارب والكاتاماران. قوموا بنزهات مائية واقضوا وقتاً أطول في الهواء الطلق.',
    ],
    'Схема понтонного пляжа' => ['en' => 'Pontoon beach layout', 'ar' => 'مخطط الشاطئ العائم'],
    'Фото 2026 года' => ['en' => 'Photo, 2026', 'ar' => 'صورة 2026'],
    'Утро у воды' => ['en' => 'Morning by the water', 'ar' => 'صباح على الماء'],
    'Вечер на террасе' => ['en' => 'Evening on the terrace', 'ar' => 'مساء على الشرفة'],
    'Вечер у воды' => ['en' => 'Evening by the water', 'ar' => 'مساء على الماء'],
    'Как жители будут пользоваться пляжем' => ['en' => 'How residents will use the beach', 'ar' => 'كيف يستخدم السكان الشاطئ'],
    'Парк с прудом для жителей поселка' => ['en' => 'A park with a pond for village residents', 'ar' => 'حديقة مع بركة لسكان القرية'],
    'Park с прудом для жителей поселка' => ['en' => 'A park with a pond for village residents', 'ar' => 'حديقة مع بركة لسكان القرية'],
    'с прудом для жителей поселка' => ['en' => 'with a pond for village residents', 'ar' => 'مع بركة لسكان القرية'],
    'Собственный ландшафтный парк площадью 8 гектаров: прогулочные и велосипедные дорожки, зоны отдыха, пруд с фонтаном, детские площадки и пространства для семейного досуга без выезда из поселка.' => [
      'en' => 'A private 8-hectare landscape park: walking and cycling paths, rest areas, a fountain pond, playgrounds and family leisure spaces without leaving the village.',
      'ar' => 'حديقة مناظر بمساحة 8 هكتارات: مسارات للمشي والدراجات ومناطق راحة وبركة بنافورة وملاعب ومساحات عائلية دون مغادرة القرية.',
    ],
    'ландшафтного парка на территории поселка' => ['en' => 'of landscape park on the village grounds', 'ar' => 'من الحديقة في أراضي القرية'],
    '10 зон' => ['en' => '10 zones', 'ar' => '10 مناطق'],
    'отдых, спорт, детские площадки, прогулки' => ['en' => 'rest, sports, playgrounds, walks', 'ar' => 'راحة ورياضة وملاعب ونزهات'],
    'Пруд' => ['en' => 'Pond', 'ar' => 'بركة'],
    'Собственный парк с прудом без выезда из поселка' => [
      'en' => 'A private park with a pond without leaving the village',
      'ar' => 'حديقة خاصة مع بركة دون مغادرة القرية',
    ],
    'Private park с прудом без выезда из поселка' => [
      'en' => 'A private park with a pond without leaving the village',
      'ar' => 'حديقة خاصة مع بركة دون مغادرة القرية',
    ],
    'с прудом без выезда из поселка' => ['en' => 'with a pond without leaving the village', 'ar' => 'مع بركة دون مغادرة القرية'],
    'Ландшафтный парк усиливает главное преимущество «Берега Песочной» — жизнь рядом с природой. Это не просто зелёная зона у дома, а полноценное пространство для прогулок, встреч, отдыха с семьёй и активного досуга без выезда из поселка.' => [
      'en' => 'The landscape park adds to Bereg Pesochnoy’s main advantage — life next to nature. It is not just a green patch by the house, but a full space for walks, meetings, family rest and active leisure without leaving the village.',
      'ar' => 'تعزّز الحديقة ميزة بيريج بيسوتشنايا — الحياة بجانب الطبيعة. ليست مجرد مساحة خضراء، بل مكان للنزهات واللقاءات وراحة العائلة دون مغادرة القرية.',
    ],
    'Это не просто зелёная зона у дома, а полноценное пространство для прогулок, встреч, отдыха с семьёй и активного досуга без выезда из поселка.' => [
      'en' => 'It is not just a green patch by the house, but a full space for walks, meetings, family rest and active leisure without leaving the village.',
      'ar' => 'ليست مجرد مساحة خضراء، بل مكان للنزهات واللقاءات وراحة العائلة دون مغادرة القرية.',
    ],
    'Зона спокойного отдыха' => ['en' => 'Quiet rest area', 'ar' => 'منطقة راحة هادئة'],
    'Зона спокойного отдыха в парке' => ['en' => 'Quiet rest area in the park', 'ar' => 'منطقة راحة هادئة في الحديقة'],
    'Детские площадки и досуговый центр' => ['en' => 'Playgrounds and a leisure center', 'ar' => 'ملاعب ومركز ترفيه'],
    'Playgrounds и досуговый центр' => ['en' => 'Playgrounds and a leisure center', 'ar' => 'ملاعب ومركز ترفيه'],
    'Игровые площадки, зоны для семейного отдыха и досуговый центр создают безопасную среду для детей и родителей.' => [
      'en' => 'Playgrounds, family rest areas and a leisure center create a safe setting for children and parents.',
      'ar' => 'الملاعب ومناطق العائلة ومركز الترفيه تخلق بيئة آمنة للأطفال والآباء.',
    ],
    'Спортплощадка и зона активного отдыха' => ['en' => 'Sports ground and active leisure area', 'ar' => 'ملعب رياضي ومنطقة نشاط'],
    'Спортивные площадки, велодорожки и зоны активного отдыха помогают проводить больше времени на свежем воздухе.' => [
      'en' => 'Sports grounds, bike paths and active leisure areas help you spend more time outdoors.',
      'ar' => 'الملاعب الرياضية ومسارات الدراجات ومناطق النشاط تساعد على قضاء وقت أطول في الهواء الطلق.',
    ],
    'Зоны парка' => ['en' => 'Park zones', 'ar' => 'مناطق الحديقة'],
    '8 Га для отдыха' => ['en' => '8 ha for rest', 'ar' => '8 هكتارات للراحة'],
    'Малые архитектурные формы' => ['en' => 'Small architectural forms', 'ar' => 'عناصر معمارية صغيرة'],
    'Собственный пруд в парке' => ['en' => 'A private pond in the park', 'ar' => 'بركة خاصة في الحديقة'],
    '30 видов деревьев' => ['en' => '30 tree species', 'ar' => '30 نوعاً من الأشجار'],
    '30 видов trees' => ['en' => '30 tree species', 'ar' => '30 نوعاً من الأشجار'],
    'видов деревьев' => ['en' => 'tree species', 'ar' => 'أنواع أشجار'],
    'Пляжная зона' => ['en' => 'Beach area', 'ar' => 'منطقة الشاطئ'],
    'В нашем парке есть все' => ['en' => 'Our park has everything', 'ar' => 'في حديقتنا كل شيء'],
    'Многофункциональный комплекс<br>ЖК «Берег Песочной»' => [
      'en' => 'Multifunctional complex<br>Bereg Pesochnoy',
      'ar' => 'مجمّع متعدد الوظائف<br>بيريج بيسوتشنايا',
    ],
    'Центр жизни посёлка. Всё под рукой. Ваше время — для семьи, отдыха и работы, а повседневные заботы мы взяли на себя.' => [
      'en' => 'The heart of village life. Everything is at hand. Your time is for family, rest and work — we take care of everyday tasks.',
      'ar' => 'قلب حياة القرية. كل شيء في متناول اليد. وقتكم للعائلة والراحة والعمل — ونحن نتولى المهام اليومية.',
    ],
    'Жизнь за городом <span class="t-accent">без компромиссов</span>' => [
      'en' => 'Country living <span class="t-accent">without compromise</span>',
      'ar' => 'حياة ريفية <span class="t-accent">بلا تنازلات</span>',
    ],
    'Жизнь за городом без компромиссов' => ['en' => 'Country living without compromise', 'ar' => 'حياة ريفية بلا تنازلات'],
    'Country living без компромиссов' => ['en' => 'Country living without compromise', 'ar' => 'حياة ريفية بلا تنازلات'],
    'без компромиссов' => ['en' => 'without compromise', 'ar' => 'بلا تنازلات'],
    'Многофункциональный комплекс — это центр жизни коттеджного посёлка «Берег Песочной». Здесь собраны все необходимые сервисы для комфортной жизни за городом: детская комната, бассейн, конференц-зал, магазин, кафе, парикмахерская, аптека, спортзал и сауна — всё в шаговой доступности от вашего дома.' => [
      'en' => 'The multifunctional complex is the heart of Bereg Pesochnoy. It brings together the services for comfortable country living: a kids’ room, pool, conference hall, shop, cafe, hair salon, pharmacy, gym and sauna — all a short walk from your home.',
      'ar' => 'المجمّع المتعدد الوظائف هو قلب بيريج بيسوتشنايا: غرفة أطفال ومسبح وقاعة مؤتمرات ومتجر ومقهى وصالون وصيدلية ورياضة وساونا — كلها على بعد خطوات من المنزل.',
    ],
    'Multifunctional complex — это центр жизни коттеджного посёлка «Bereg Pesochnoy». Здесь собраны все необходимые сервисы для комфортной жизни за городом: детская комната, бассейн, конференц-зал, магазин, кафе, парикмахерская, аптека, спортзал и сауна — всё в шаговой доступности от вашего дома.' => [
      'en' => 'The multifunctional complex is the heart of Bereg Pesochnoy. It brings together the services for comfortable country living: a kids’ room, pool, conference hall, shop, cafe, hair salon, pharmacy, gym and sauna — all a short walk from your home.',
      'ar' => 'المجمّع المتعدد الوظائف هو قلب بيريج بيسوتشنايا: غرفة أطفال ومسبح وقاعة مؤتمرات ومتجر ومقهى وصالون وصيدلية ورياضة وساونا — كلها على بعد خطوات من المنزل.',
    ],
    '— это центр жизни коттеджного посёлка' => ['en' => 'is the heart of the cottage village', 'ar' => 'هو قلب قرية الكوتيدجات'],
    'Здесь собраны все необходимые сервисы для комфортной жизни за городом: детская комната, бассейн, конференц-зал, магазин, кафе, парикмахерская, аптека, спортзал и сауна — всё в шаговой доступности от вашего дома.' => [
      'en' => 'Here you will find the services for comfortable country living: a kids’ room, pool, conference hall, shop, cafe, hair salon, pharmacy, gym and sauna — all a short walk from your home.',
      'ar' => 'هنا كل الخدمات لحياة ريفية مريحة: غرفة أطفال ومسبح وقاعة مؤتمرات ومتجر ومقهى وصالون وصيدلية ورياضة وساونا — على بعد خطوات من المنزل.',
    ],
    'Детская комната' => ['en' => 'Kids’ room', 'ar' => 'غرفة الأطفال'],
    'Ваш ребенок в безопасности под присмотром педагога. Вы получаете свободное время для себя, не выезжая из посёлка.' => [
      'en' => 'Your child is safe with a teacher. You get free time for yourself without leaving the village.',
      'ar' => 'طفلكم بأمان مع معلّم. تحصلون على وقت لأنفسكم دون مغادرة القرية.',
    ],
    'Бассейн' => ['en' => 'Swimming pool', 'ar' => 'مسبح'],
    'Забудьте о пробках до спортклуба. Поддерживайте себя в отличной форме круглый год прямо в жилом комплексе.' => [
      'en' => 'Forget the traffic to a city gym. Stay in shape all year right on the estate.',
      'ar' => 'انسوا زحمة الطريق إلى النادي. حافظوا على لياقتكم طوال العام داخل المجمّع.',
    ],
    'Конференц-зал' => ['en' => 'Conference hall', 'ar' => 'قاعة مؤتمرات'],
    'Работайте и принимайте клиентов, не тратя время на дорогу. Всё необходимое для продуктивной работы уже здесь.' => [
      'en' => 'Work and meet clients without the commute. Everything you need for productive work is already here.',
      'ar' => 'اعملوا واستقبلوا العملاء دون الطريق. كل ما يلزم للعمل المنتج موجود هنا.',
    ],
    'Магазин продуктов' => ['en' => 'Grocery store', 'ar' => 'متجر بقالة'],
    'Свежий хлеб, молоко и всё необходимое для дома в шаговой доступности на территории поселка. Без поездок в город.' => [
      'en' => 'Fresh bread, milk and everyday groceries a short walk away. No trips to the city.',
      'ar' => 'خبز طازج وحليب وكل احتياجات المنزل على بعد خطوات. دون الذهاب إلى المدينة.',
    ],
    'Кафе' => ['en' => 'Cafe', 'ar' => 'مقهى'],
    'Место для встреч, семейных ужинов и рабочих бесед. Приходите и наслаждайтесь атмосферой и вкусной едой.' => [
      'en' => 'A place for meetings, family dinners and work talks. Come for the atmosphere and good food.',
      'ar' => 'مكان للقاءات وعشاء العائلة وأحاديث العمل. تعالوا للاستمتاع بالأجواء والطعام.',
    ],
    'Парикмахерская' => ['en' => 'Hair salon', 'ar' => 'صالون شعر'],
    'Салон и уход за собой в Bereg Pesochnoy. Экономьте время, которое раньше уходило на дорогу в город.' => [
      'en' => 'A salon and self-care in Bereg Pesochnoy. Save the time you used to spend going to the city.',
      'ar' => 'صالون وعناية في بيريج بيسوتشنايا. وفّروا الوقت الذي كان يضيع في الطريق إلى المدينة.',
    ],
    'Аптека' => ['en' => 'Pharmacy', 'ar' => 'صيدلية'],
    'Если кто-то заболел, всё необходимое есть рядом. Ваше спокойствие и безопасность — наша главная забота.' => [
      'en' => 'If someone falls ill, everything you need is nearby. Your peace of mind is our main concern.',
      'ar' => 'إذا مرض أحد، كل ما يلزم قريب. راحتكم وأمانكم أولويتنا.',
    ],
    'Спортзал' => ['en' => 'Gym', 'ar' => 'صالة رياضة'],
    'Sports зал' => ['en' => 'Gym', 'ar' => 'صالة رياضة'],
    'Фитнес-зал с современным оборудованием рядом с домом. Занимайтесь в удобном ритме, не тратя время на дорогу.' => [
      'en' => 'A fitness room with modern equipment next to home. Train at your own pace without the commute.',
      'ar' => 'صالة لياقة حديثة بجانب المنزل. تمرّنوا بإيقاعكم دون الطريق.',
    ],
    'Сауна' => ['en' => 'Sauna', 'ar' => 'ساونا'],
    'Сауна, горячий пар, спа-процедуры и полное восстановление сил без поездок в город.' => [
      'en' => 'A sauna, steam, spa treatments and a full reset without trips to the city.',
      'ar' => 'ساونا وبخار وعلاجات سبا واستعادة كاملة دون الذهاب إلى المدينة.',
    ],
    'Центр жизни посёлка.<br>Всё под рукой' => ['en' => 'The heart of the village.<br>Everything at hand', 'ar' => 'قلب القرية.<br>كل شيء في متناول اليد'],
    'Центр жизни посёлка.' => ['en' => 'The heart of the village.', 'ar' => 'قلب القرية.'],
    'Всё под рукой' => ['en' => 'Everything at hand', 'ar' => 'كل شيء في متناول اليد'],
    'Часто<br>задаваемые<br>вопросы' => ['en' => 'Frequently<br>asked<br>questions', 'ar' => 'أسئلة<br>شائعة'],
    'Что входит в многофункциональный комплекс?' => ['en' => 'What is in the multifunctional complex?', 'ar' => 'ماذا يوجد في المجمّع المتعدد الوظائف؟'],
    'На территории МФК работают детская комната, бассейн, конференц-зал, продуктовый магазин, кафе, парикмахерская, аптека, спортзал и сауна — всё для повседневного комфорта жителей посёлка.' => [
      'en' => 'The complex has a kids’ room, pool, conference hall, grocery store, cafe, hair salon, pharmacy, gym and sauna — everything for residents’ everyday comfort.',
      'ar' => 'في المجمّع غرفة أطفال ومسبح وقاعة مؤتمرات ومتجر ومقهى وصالون وصيدلية ورياضة وساونا — كل شيء لراحة السكان اليومية.',
    ],
    'Могут ли пользоваться сервисами только жители посёлка?' => [
      'en' => 'Can only village residents use the services?',
      'ar' => 'هل الخدمات لسكان القرية فقط؟',
    ],
    'Большинство сервисов МФК ориентированы на жителей КП «Берег Песочной» и созданы для их повседневных потребностей. Подробности по каждому сервису уточняйте у менеджера.' => [
      'en' => 'Most services are meant for Bereg Pesochnoy residents and their everyday needs. Ask a manager for details on each service.',
      'ar' => 'معظم الخدمات موجّهة لسكان بيريج بيسوتشنايا واحتياجاتهم اليومية. اسألوا المدير عن تفاصيل كل خدمة.',
    ],
    'Большинство сервисов МФК ориентированы на жителей Village «Bereg Pesochnoy» и созданы для их повседневных потребностей. Подробности по каждому сервису уточняйте у менеджера.' => [
      'en' => 'Most services are meant for Bereg Pesochnoy residents and their everyday needs. Ask a manager for details on each service.',
      'ar' => 'معظم الخدمات موجّهة لسكان بيريج بيسوتشنايا واحتياجاتهم اليومية. اسألوا المدير عن تفاصيل كل خدمة.',
    ],
    'Где находится МФК?' => ['en' => 'Where is the complex?', 'ar' => 'أين يقع المجمّع؟'],
    'Многофункциональный комплекс расположен на территории коттеджного посёлка «Берег Песочной» в Истринском районе Московской области, примерно в 45 км от МКАД.' => [
      'en' => 'The multifunctional complex is on the grounds of Bereg Pesochnoy in the Istra district of the Moscow Region, about 45 km from MKAD.',
      'ar' => 'يقع المجمّع في أراضي بيريج بيسوتشنايا بمنطقة إسترا، على بعد نحو 45 كم من طريق موسكو الدائري.',
    ],
    'расположен на территории коттеджного посёлка «Bereg Pesochnoy» в Истринском районе Московской области, примерно в 45 km from MKAD.' => [
      'en' => 'is on the grounds of Bereg Pesochnoy in the Istra district of the Moscow Region, about 45 km from MKAD.',
      'ar' => 'يقع في أراضي بيريج بيسوتشنايا بمنطقة إسترا، على بعد نحو 45 كم من طريق موسكو الدائري.',
    ],
    'Можно ли посмотреть комплекс лично?' => ['en' => 'Can I visit the complex in person?', 'ar' => 'هل يمكن زيارة المجمّع شخصياً؟'],
    'Да, запишитесь на экскурсию — покажем территорию посёлка, инфраструктуру и ответим на все вопросы.' => [
      'en' => 'Yes, book a tour — we will show the village, the infrastructure and answer every question.',
      'ar' => 'نعم، احجزوا جولة — سنعرض القرية والبنية ونجيب عن كل الأسئلة.',
    ],
    'Да, запишитесь a tour — покажем территорию посёлка, инфраструктуру и ответим на все вопросы.' => [
      'en' => 'Yes, book a tour — we will show the village, the infrastructure and answer every question.',
      'ar' => 'نعم، احجزوا جولة — سنعرض القرية والبنية ونجيب عن كل الأسئلة.',
    ],
    'Свежая зелень круглый год —' => ['en' => 'Fresh greens all year —', 'ar' => 'خضرة طازجة طوال العام —'],
    'прямо в поселке.' => ['en' => 'right in the village.', 'ar' => 'مباشرة في القرية.'],
    'прямо в village.' => ['en' => 'right in the village.', 'ar' => 'مباشرة في القرية.'],
    'В ЖК «Берег Песочной» загородная жизнь становится самодостаточной: природа, инфраструктура и собственная вертикальная ферма объединяются в одну среду для постоянного проживания.' => [
      'en' => 'In Bereg Pesochnoy country living becomes self-sufficient: nature, infrastructure and our own vertical farm come together as one setting for year-round life.',
      'ar' => 'في بيريج بيسوتشنايا تصبح الحياة الريفية مكتفية: الطبيعة والبنية ومزرعتنا العمودية تجتمع في بيئة للسكن الدائم.',
    ],
    'В Bereg Pesochnoy residence загородная жизнь становится самодостаточной: природа, инфраструктура и собственная вертикальная ферма объединяются в одну среду для постоянного проживания.' => [
      'en' => 'In Bereg Pesochnoy country living becomes self-sufficient: nature, infrastructure and our own vertical farm come together as one setting for year-round life.',
      'ar' => 'في بيريج بيسوتشنايا تصبح الحياة الريفية مكتفية: الطبيعة والبنية ومزرعتنا العمودية تجتمع في بيئة للسكن الدائم.',
    ],
    'загородная жизнь становится самодостаточной: природа, инфраструктура и собственная вертикальная ферма объединяются в одну среду для постоянного проживания.' => [
      'en' => 'country living becomes self-sufficient: nature, infrastructure and our own vertical farm come together as one setting for year-round life.',
      'ar' => 'تصبح الحياة الريفية مكتفية: الطبيعة والبنية ومزرعتنا العمودية تجتمع في بيئة للسكن الدائم.',
    ],
    'Посмотреть ферму' => ['en' => 'See the farm', 'ar' => 'شاهد المزرعة'],
    'Свежая зелень' => ['en' => 'Fresh greens', 'ar' => 'خضرة طازجة'],
    'Полезные сервисы прямо внутри поселка' => ['en' => 'Useful services right inside the village', 'ar' => 'خدمات مفيدة داخل القرية'],
    'Каждый день' => ['en' => 'Every day', 'ar' => 'كل يوم'],
    'свежая зелень к вашему столу.' => ['en' => 'fresh greens on your table.', 'ar' => 'خضرة طازجة على مائدتكم.'],
    'Растет рядом' => ['en' => 'Grows nearby', 'ar' => 'تنمو بالقرب'],
    'выращивается прямо внутри поселка' => ['en' => 'grown right inside the village', 'ar' => 'تُزرع داخل القرية'],
    'Круглый год' => ['en' => 'All year', 'ar' => 'طوال العام'],
    'Сезон остается за дверью вертикальной фермы' => ['en' => 'The season stays outside the vertical farm', 'ar' => 'الموسم يبقى خارج المزرعة العمودية'],
    'Вертикальная ферма в поселке' => ['en' => 'Vertical farm in the village', 'ar' => 'مزرعة عمودية في القرية'],
    'Вертикальная ферма в village' => ['en' => 'Vertical farm in the village', 'ar' => 'مزرعة عمودية في القرية'],
    'За городом<br><span class="t-accent">не значит вдали от комфорта</span>' => [
      'en' => 'Living outside the city<br><span class="t-accent">does not mean far from comfort</span>',
      'ar' => 'العيش خارج المدينة<br><span class="t-accent">لا يعني بعيداً عن الراحة</span>',
    ],
    'не значит вдали от комфорта' => ['en' => 'does not mean far from comfort', 'ar' => 'لا يعني بعيداً عن الراحة'],
    'В обычном загородном проекте инфраструктура часто заканчивается дорогами, охраной и прогулочными зонами. В «Береге Песочной» идея шире: полезные сервисы становятся частью самой территории. Собственная вертикальная ферма — один из примеров такой среды.' => [
      'en' => 'In a typical country project infrastructure often stops at roads, security and walking areas. In Bereg Pesochnoy the idea is wider: useful services become part of the land itself. Our vertical farm is one example of that setting.',
      'ar' => 'في مشروع ريفي عادي غالباً ما تتوقف البنية عند الطرق والحراسة ومناطق التنزه. في بيريج بيسوتشنايا الفكرة أوسع: الخدمات المفيدة جزء من الأرض نفسها. مزرعتنا العمودية مثال على ذلك.',
    ],
    'Дом определяет, где вы живете.<br><span class="t-accent">Среда — как вы живете</span>' => [
      'en' => 'The house decides where you live.<br><span class="t-accent">The setting decides how you live</span>',
      'ar' => 'المنزل يحدّد أين تعيشون.<br><span class="t-accent">والبيئة كيف تعيشون</span>',
    ],
    'Среда — как вы живете' => ['en' => 'The setting decides how you live', 'ar' => 'البيئة تحدّد كيف تعيشون'],
    'Поэтому ферма здесь важна не сама по себе. Она показывает подход к проекту: создавать больше возможностей внутри поселка и делать постоянную загородную жизнь удобнее.' => [
      'en' => 'That is why the farm matters — not for its own sake, but as a sign of the approach: more opportunities inside the village and an easier year-round country life.',
      'ar' => 'لذلك تهم المزرعة لا لذاتها، بل كنهج: فرص أكثر داخل القرية وحياة ريفية دائمة أيسر.',
    ],
    'Контейнерная ферма прямо на территории' => ['en' => 'A container farm right on the grounds', 'ar' => 'مزرعة حاوية في الموقع'],
    'Снаружи — аккуратный современный объект. Внутри — многоуровневая ферма с собственным микроклиматом для круглогодичного выращивания свежей зелени.' => [
      'en' => 'Outside — a neat modern building. Inside — a multi-level farm with its own climate for growing fresh greens all year.',
      'ar' => 'من الخارج مبنى حديث أنيق. ومن الداخل مزرعة متعددة المستويات بمناخها الخاص لزراعة الخضرة طوال العام.',
    ],
    'Современная технология, интегрированная в ландшафт поселка' => [
      'en' => 'Modern technology built into the village landscape',
      'ar' => 'تقنية حديثة مندمجة في منظر القرية',
    ],
    'Свежая зелень независимо от внешнего сезона' => ['en' => 'Fresh greens regardless of the season outside', 'ar' => 'خضرة طازجة مهما كان الموسم'],
    'Минимальный путь от выращивания до жителей' => ['en' => 'The shortest path from growing to residents', 'ar' => 'أقصر طريق من الزراعة إلى السكان'],
    'Инфраструктурный объект, который усиливает образ проекта' => [
      'en' => 'An infrastructure object that strengthens the project’s image',
      'ar' => 'عنصر بنية يعزّز صورة المشروع',
    ],
    'Снаружи' => ['en' => 'Outside', 'ar' => 'الخارج'],
    'Внутри' => ['en' => 'Inside', 'ar' => 'الداخل'],
    'Утро в поселке' => ['en' => 'Morning in the village', 'ar' => 'صباح في القرية'],
    'Утро в village' => ['en' => 'Morning in the village', 'ar' => 'صباح في القرية'],
    'Утро начинается<br><span class="t-accent">не с дороги в город</span>' => [
      'en' => 'The morning starts<br><span class="t-accent">not with a trip to the city</span>',
      'ar' => 'يبدأ الصباح<br><span class="t-accent">لا برحلة إلى المدينة</span>',
    ],
    'не с дороги в город' => ['en' => 'not with a trip to the city', 'ar' => 'لا برحلة إلى المدينة'],
    'Свежая зелень выращивается в нескольких минутах от вашего дома. Лес начинается за участком. А полезная инфраструктура остается внутри поселка. Так выглядит загородная жизнь, продуманная для постоянного проживания.' => [
      'en' => 'Fresh greens grow a few minutes from your house. The forest starts beyond the plot. And useful infrastructure stays inside the village. That is country living designed for year-round life.',
      'ar' => 'تُزرع الخضرة على بعد دقائق من منزلكم. الغابة تبدأ خلف القطعة. والبنية المفيدة تبقى داخل القرية. هكذا تبدو حياة ريفية مصممة للسكن الدائم.',
    ],
    'Лето внутри <span class="t-accent">круглый год</span>' => [
      'en' => 'Summer inside <span class="t-accent">all year</span>',
      'ar' => 'صيف في الداخل <span class="t-accent">طوال العام</span>',
    ],
    'Лето внутри круглый год' => ['en' => 'Summer inside all year', 'ar' => 'صيف في الداخل طوال العام'],
    'Внутри контейнера создается контролируемая среда для растений. Освещение, температура и влажность поддерживаются независимо от внешнего сезона.' => [
      'en' => 'Inside the container a controlled climate is created for the plants. Light, temperature and humidity stay stable whatever the season outside.',
      'ar' => 'داخل الحاوية تُصنع بيئة محكمة للنباتات. الإضاءة والحرارة والرطوبة ثابتة مهما كان الموسم في الخارج.',
    ],
    'Многоуровневое выращивание' => ['en' => 'Multi-level growing', 'ar' => 'زراعة متعددة المستويات'],
    'Контролируемый микроклимат' => ['en' => 'Controlled microclimate', 'ar' => 'مناخ دقيق محكوم'],
    'Круглогодичный цикл' => ['en' => 'Year-round cycle', 'ar' => 'دورة على مدار العام'],
    'Минимальный путь от фермы до жителей' => ['en' => 'The shortest path from farm to residents', 'ar' => 'أقصر طريق من المزرعة إلى السكان'],
    'Руккола' => ['en' => 'Arugula', 'ar' => 'جرجير'],
    'Микрозелень' => ['en' => 'Microgreens', 'ar' => 'ميكروجرينز'],
    'Неповторимая свежесть и глубина вкуса' => ['en' => 'Unique freshness and depth of flavor', 'ar' => 'نضارة فريدة وعمق في الطعم'],
    'Кладовая витаминов и минералов' => ['en' => 'A store of vitamins and minerals', 'ar' => 'مخزن فيتامينات ومعادن'],
    'Идеальна для контроля веса' => ['en' => 'Ideal for weight control', 'ar' => 'مثالية للتحكم بالوزن'],
    'Мощная антиоксидантная защита' => ['en' => 'Strong antioxidant protection', 'ar' => 'حماية قوية مضادة للأكسدة'],
    'Не про технологию. <span class="t-accent">Про подход.</span>' => [
      'en' => 'Not about the technology. <span class="t-accent">About the approach.</span>',
      'ar' => 'ليس عن التقنية. <span class="t-accent">عن النهج.</span>',
    ],
    'Не про технологию. Про подход.' => ['en' => 'Not about the technology. About the approach.', 'ar' => 'ليس عن التقنية. عن النهج.'],
    'Про подход.' => ['en' => 'About the approach.', 'ar' => 'عن النهج.'],
    'Когда даже такие детали продуманы заранее, иначе воспринимается весь проект. Покупатель видит не набор участков, а единую систему: дом, природа, инфраструктура и повседневные сервисы.' => [
      'en' => 'When even these details are thought through in advance, the whole project feels different. A buyer sees not a set of plots, but one system: home, nature, infrastructure and everyday services.',
      'ar' => 'عندما تُفكَّر حتى هذه التفاصيل مسبقاً، يبدو المشروع كله مختلفاً. المشتري يرى لا مجموعة قطع، بل منظومة واحدة: منزل وطبيعة وبنية وخدمات يومية.',
    ],
    'Самодостаточная среда' => ['en' => 'A self-sufficient setting', 'ar' => 'بيئة مكتفية'],
    'Своя инфраструктура внутри поселка делает загородную жизнь менее зависимой от города и повышает ощущаемую ценность каждого дома.' => [
      'en' => 'Its own infrastructure inside the village makes country life less dependent on the city and raises the felt value of every house.',
      'ar' => 'بنيتها داخل القرية تجعل الحياة الريفية أقل اعتماداً على المدينة وترفع قيمة كل منزل.',
    ],
    'Удобно работать, приятно жить' => ['en' => 'Easy to work, pleasant to live', 'ar' => 'عمل مريح وحياة ممتعة'],
    'В посёлке есть всё необходимое для комфортной работы из дома. Спокойная атмосфера и близость к природе помогают сосредоточиться, а современная инфраструктура позволяет оставаться на связи и решать рабочие задачи, не уезжая в город.' => [
      'en' => 'The village has everything for comfortable work from home. A calm setting and nature nearby help you focus, and modern infrastructure keeps you connected without going to the city.',
      'ar' => 'في القرية كل ما يلزم للعمل المريح من المنزل. الهدوء وقرب الطبيعة يساعدان على التركيز، والبنية الحديثة تبقيكم على تواصل دون الذهاب إلى المدينة.',
    ],
    'Надёжная инвестиция в будущее' => ['en' => 'A reliable investment in the future', 'ar' => 'استثمار موثوق في المستقبل'],
    'Недвижимость в посёлке — это не только комфорт для жизни, но и перспективный актив. Продуманная инфраструктура, современная архитектура и развитие территории поддерживают привлекательность недвижимости и её потенциал роста в стоимости.' => [
      'en' => 'Property in the village is not only comfort for living, but a promising asset. Thought-out infrastructure, modern architecture and the development of the land support its appeal and growth potential.',
      'ar' => 'العقار في القرية ليس راحة للعيش فقط، بل أصل واعد. البنية المدروسة والعمارة الحديثة وتطوّر الأرض تدعم جاذبيته وإمكانية ارتفاع قيمته.',
    ],
    'Недвижимость в посёлке — это не только комфорт for living, но и перспективный актив. Продуманная инфраструктура, современная архитектура и развитие территории поддерживают привлекательность недвижимости и её потенциал роста в стоимости.' => [
      'en' => 'Property in the village is not only comfort for living, but a promising asset. Thought-out infrastructure, modern architecture and the development of the land support its appeal and growth potential.',
      'ar' => 'العقار في القرية ليس راحة للعيش فقط، بل أصل واعد. البنية المدروسة والعمارة الحديثة وتطوّر الأرض تدعم جاذبيته وإمكانية ارتفاع قيمته.',
    ],
    'Запишитесь на экскурсию в посёлок' => ['en' => 'Book a tour of the village', 'ar' => 'احجزوا جولة في القرية'],
    'Запишитесь a tour в посёлок' => ['en' => 'Book a tour of the village', 'ar' => 'احجزوا جولة في القرية'],
    'Лучше один раз увидеть всё своими глазами. Прогуляйтесь по территории, познакомьтесь с домами и инфраструктурой, оцените атмосферу и задайте все интересующие вопросы.' => [
      'en' => 'It is better to see everything once with your own eyes. Walk the grounds, see the houses and infrastructure, feel the atmosphere and ask every question you have.',
      'ar' => 'الأفضل أن تروا كل شيء بأنفسكم. تنزّهوا في الأرض، شاهدوا المنازل والبنية، حسّوا الأجواء واسألوا كل ما يهمكم.',
    ],
    'Park с прудом в Village «Bereg Pesochnoy» — ландшафтный парк 8 ha' => [
      'en' => 'A park with a pond in Bereg Pesochnoy — an 8 ha landscape park',
      'ar' => 'حديقة مع بركة في بيريج بيسوتشنايا — حديقة 8 هكتارات',
    ],
    'Свежая зелень круглый год' => ['en' => 'Fresh greens all year', 'ar' => 'خضرة طازجة طوال العام'],
    'Мфк' => ['en' => 'Multifunctional complex', 'ar' => 'مجمّع متعدد الوظائف'],
    'Назад' => ['en' => 'Back', 'ar' => 'رجوع'],
    'Вперёд' => ['en' => 'Forward', 'ar' => 'التالي'],
    'Узнать больше' => ['en' => 'Learn more', 'ar' => 'اعرف المزيد'],
    'For the family спокойный формат рядом с домом' => [
      'en' => 'For the family — a quiet format next to home',
      'ar' => 'للعائلة — صيغة هادئة بجانب المنزل',
    ],
    'Среда поселка Берег Песочной' => ['en' => 'The setting of Bereg Pesochnoy', 'ar' => 'بيئة بيريج بيسوتشنايا'],
    'Среда поселка Bereg Pesochnoy' => ['en' => 'The setting of Bereg Pesochnoy', 'ar' => 'بيئة بيريج بيسوتشنايا'],
    'Лендинг Понтон — экскурсия' => ['en' => 'Pontoon landing — tour', 'ar' => 'صفحة الشاطئ — جولة'],
