    'Камера 1 (Park, ул. Радужная)' => ['en' => 'Camera 1 (Park, Raduzhnaya St.)', 'ar' => 'كاميرا 1 (الحديقة، شارع رادوجنايا)'],
    'Камера 2 (Въездная группа, ул. Лесная / Парковая)' => ['en' => 'Camera 2 (Entrance, Lesnaya / Parkovaya St.)', 'ar' => 'كاميرا 2 (المدخل، ليسنايا / باركوفايا)'],
    'Камера 3 (ул. Парковая / Радужная)' => ['en' => 'Camera 3 (Parkovaya / Raduzhnaya St.)', 'ar' => 'كاميرا 3 (باركوفايا / رادوجنايا)'],
    'Камера 4 (ул. Парковая )' => ['en' => 'Camera 4 (Parkovaya St.)', 'ar' => 'كاميرا 4 (شارع باركوفايا)'],
    'Камера 5 (ул.Парковая)' => ['en' => 'Camera 5 (Parkovaya St.)', 'ar' => 'كاميرا 5 (شارع باركوفايا)'],
    'Камера 6 (Водопад)' => ['en' => 'Camera 6 (Waterfall)', 'ar' => 'كاميرا 6 (الشلال)'],
    'ул. Радужная' => ['en' => 'Raduzhnaya St.', 'ar' => 'شارع رادوجنايا'],
    'ул. Лесная' => ['en' => 'Lesnaya St.', 'ar' => 'شارع ليسنايا'],
    'ул. Парковая' => ['en' => 'Parkovaya St.', 'ar' => 'شارع باركوفايا'],
    'ул.Парковая' => ['en' => 'Parkovaya St.', 'ar' => 'شارع باركوفايا'],
    'Въездная группа' => ['en' => 'Entrance group', 'ar' => 'مجموعة المدخل'],
    'Водопад' => ['en' => 'Waterfall', 'ar' => 'شلال'],
    'Камера ' => ['en' => 'Camera ', 'ar' => 'كاميرا '],
    'Строительство домов в поселке по технологии БЭНПАН' => [
      'en' => 'House construction in the village using BENPAN technology',
      'ar' => 'بناء المنازل في القرية بتقنية بنبان',
    ],
    'Construction домов в village по технологии БЭНПАН' => [
      'en' => 'House construction in the village using BENPAN technology',
      'ar' => 'بناء المنازل في القرية بتقنية بنبان',
    ],
    'Дома в поселке строятся из современных сертифицированных многослойных утепленных железобетонных панелей произведенных по технологии БЭНПАН.' => [
      'en' => 'Houses in the village are built from certified multi-layer insulated reinforced-concrete panels made with BENPAN technology.',
      'ar' => 'تُبنى منازل القرية من ألواح خرسانية معزولة متعددة الطبقات معتمدة بتقنية بنبان.',
    ],
    'Технология <br class="title-br"> строительства<br>домов в поселке<br><span>берег песочной</span>' => [
      'en' => 'House construction<br class="title-br"> technology<br>in the village of<br><span>Bereg Pesochnoy</span>',
      'ar' => 'تقنية بناء<br class="title-br"> المنازل<br>في قرية<br><span>بيريج بيسوتشنايا</span>',
    ],
    'Технология строительства домов в поселке берег песочной' => [
      'en' => 'House construction technology in the village of Bereg Pesochnoy',
      'ar' => 'تقنية بناء المنازل في قرية بيريج بيسوتشنايا',
    ],
    'Технологии' => ['en' => 'Technology', 'ar' => 'التقنية'],
    'БЭНПАН™ - инновационная технология проектирования и производства железобетонных конструкций для малоэтажного строительства. Продукция БЭНПАН™ внесена в Московский территориальный строительный каталог (МТСК) и' => [
      'en' => 'BENPAN™ is an innovative technology for designing and producing reinforced-concrete structures for low-rise construction. BENPAN™ products are listed in the Moscow territorial construction catalog (MTSK) and',
      'ar' => 'بنبان™ تقنية مبتكرة لتصميم وإنتاج منشآت خرسانية للمباني منخفضة الارتفاع. منتجات بنبان™ مدرجة في كتالوج موسكو الإنشائي (MTSK) و',
    ],
    'отмечена' => ['en' => 'marked', 'ar' => 'مذكورة'],
    'как инновационная' => ['en' => 'as innovative', 'ar' => 'كمبتكرة'],
    'низкие расходы<br>на содержание<br>дома' => ['en' => 'low<br>maintenance<br>costs', 'ar' => 'تكاليف<br>صيانة<br>منخفضة'],
    'высокая скорость<br> строительства' => ['en' => 'high<br>construction speed', 'ar' => 'سرعة بناء<br>عالية'],
    'срок службы<br> жб панелей' => ['en' => 'service life<br>of RC panels', 'ar' => 'عمر<br>الألواح الخرسانية'],
    'Лаборатория БЭНПАН™ проводит испытания продукции собственного производства на соответствие государственным стандартам (ГОСТ) и нормативным требованиям, предъявляемым к таким изделиям. Вся продукция соответствует ГОСТ 18979-2014 «Плиты железобетонные для стен зданий. Технические условия».' => [
      'en' => 'The BENPAN™ lab tests its own products against state standards (GOST) and the regulations for such items. All products comply with GOST 18979-2014 “Reinforced-concrete wall slabs. Specifications.”',
      'ar' => 'مختبر بنبان™ يختبر منتجاته وفق المعايير الحكومية (GOST) والمتطلبات الخاصة بهذه المنتجات. كل المنتجات مطابقة لـ GOST 18979-2014.',
    ],
    'Сертификаты соответствия установленным требованиям' => ['en' => 'Certificates of conformity', 'ar' => 'شهادات المطابقة'],
    'Сертификаты на ЖБ панели:' => ['en' => 'Certificates for RC panels:', 'ar' => 'شهادات الألواح الخرسانية:'],
    'Преимущества<br>технологии БЭНПАН™' => ['en' => 'Advantages<br>of BENPAN™ technology', 'ar' => 'مزايا<br>تقنية بنبان™'],
    'Преимущества технологии БЭНПАН™' => ['en' => 'Advantages of BENPAN™ technology', 'ar' => 'مزايا تقنية بنبان™'],
    'Утепленные<br>энергоэффективные<br>многослойные панели' => [
      'en' => 'Insulated<br>energy-efficient<br>multi-layer panels',
      'ar' => 'ألواح متعددة الطبقات<br>معزولة<br>موفرة للطاقة',
    ],
    'Железобетонная стеновая панель БЭНПАН выполняет роль как внешних, так и внутренних несущих стен, что обеспечивается ее структурной особенностью — ребрами жесткости. Использование ребер уменьшает вес панелей и нагрузку на фундамент. Панель имеет двух или трехслойную конструкцию, состоящую из наружного слоя фибробетона и внутреннего теплоизоляционного.' => [
      'en' => 'A BENPAN wall panel works as both an external and an internal load-bearing wall thanks to its stiffening ribs. The ribs reduce panel weight and the load on the foundation. The panel has a two- or three-layer structure: an outer fibre-concrete layer and inner insulation.',
      'ar' => 'لوحة جدار بنبان تعمل كجدار حامل خارجي وداخلي بفضل أضلاع التثبيت. تقلل الأضلاع الوزن والحمل على الأساس. اللوحة طبقتان أو ثلاث: خرسانة ليفية خارجية وعزل داخلي.',
    ],
    'Бесшумность<br>и экологичность' => ['en' => 'Quietness<br>and eco-safety', 'ar' => 'هدوء<br>وصداقة للبيئة'],
    'Встроенная теплоизоляция прекрасно поглощает звук и служит дополнительной звукоизоляцией. В доме БЭНПАН практически не слышен уличный шум, а благодаря шумоизоляции в железобетонных плитах перекрытий на втором этаже можно ходить, танцевать или слушать музыку, не мешая жителям первого этажа.' => [
      'en' => 'Built-in insulation absorbs sound well and adds extra acoustic protection. In a BENPAN house street noise is barely heard, and thanks to the sound insulation in the floor slabs you can walk, dance or listen to music upstairs without disturbing the first floor.',
      'ar' => 'العزل المدمج يمتص الصوت جيداً. في منزل بنبان لا يكاد يُسمع ضجيج الشارع، وبفضل عزل ألواح السقف يمكن المشي أو الرقص في الطابق الثاني دون إزعاج الأول.',
    ],
    'жителям первого этажа' => ['en' => 'residents on the first floor', 'ar' => 'سكان الطابق الأول'],
    'первого этажа' => ['en' => 'the first floor', 'ar' => 'الطابق الأول'],
    'первого floors' => ['en' => 'the first floor', 'ar' => 'الطابق الأول'],
    'Железобетонные изделия БЭНПАН имеют сертификат экологической безопасности российской системы сертификации ЭКОСЕРТИФИКА и международный экологический сертификат ISO 14001' => [
      'en' => 'BENPAN reinforced-concrete products have an eco-safety certificate from the Russian ECOCERTIFICA system and the international ISO 14001 environmental certificate',
      'ar' => 'منتجات بنبان الخرسانية حاصلة على شهادة بيئية من إيكوسيرتيفيكا الروسية وعلى شهادة ISO 14001',
    ],
    'Заводские каналы <br>для коммуникаций <br>внутри стен' => [
      'en' => 'Factory channels<br>for utilities<br>inside the walls',
      'ar' => 'قنوات مصنع<br>للمرافق<br>داخل الجدران',
    ],
    'Внутренняя несущая стена БЭНПАН позволяет разместить вентиляционные каналы, стояки водопровода, канализации, электрику и подрозетники. Во внешних стенах проходят каналы к подрозетникам. При изготовлении панели возможно заложить нишу под стандартный распределительный щит.' => [
      'en' => 'An internal BENPAN load-bearing wall can take ventilation ducts, water and sewage risers, electrics and socket boxes. External walls have channels to the sockets. A niche for a standard distribution board can be built into the panel.',
      'ar' => 'الجدار الحامل الداخلي في بنبان يتسع لقنوات التهوية ورافعات الماء والصرف والكهرباء وعلب المقابس. في الجدران الخارجية قنوات إلى المقابس. يمكن ترك تجويف للوحة توزيع قياسية.',
    ],
    'Готовые фасадные <br>решения' => ['en' => 'Ready facade<br>solutions', 'ar' => 'حلول واجهات<br>جاهزة'],
    'Ready фасадные <br>решения' => ['en' => 'Ready facade<br>solutions', 'ar' => 'حلول واجهات<br>جاهزة'],
    'Если вы заказываете дом БЭНПАН, то спектр фасадных решений ограничен только вашей фантазией. Можно использовать любые материалы: керамогранит и алюкобонд, фиброцементные, композитные и терракотовые панели, дерево и камень, клинкер и штукатурку.' => [
      'en' => 'If you order a BENPAN house, facade options are limited only by your imagination. You can use porcelain stoneware and alucobond, fibre-cement, composite and terracotta panels, wood and stone, clinker and plaster.',
      'ar' => 'إذا طلبتم منزل بنبان فخيارات الواجهة محدودة بخيالكم فقط: بورسلان وألوكوبوند وألواح إسمنت ليفي ومركّبة وتراكوتا وخشب وحجر وكلينكر ولياسة.',
    ],
    'испытания<br> строительных<br> конструкций' => ['en' => 'tests of<br> building<br> structures', 'ar' => 'اختبارات<br> المنشآت<br> الإنشائية'],
    'Монтаж дома' => ['en' => 'House assembly', 'ar' => 'تركيب المنزل'],
    'Огнестойкость БЭНПАН ПРЕМИУМ' => ['en' => 'Fire resistance of BENPAN PREMIUM', 'ar' => 'مقاومة الحريق بنبان بريميوم'],
    'Испытание нагрузкой' => ['en' => 'Load test', 'ar' => 'اختبار الحمل'],
    'Огнестойкость БЭНПАН+' => ['en' => 'Fire resistance of BENPAN+', 'ar' => 'مقاومة الحريق بنبان+'],
    'отзывы<br>о технологии' => ['en' => 'reviews<br>of the technology', 'ar' => 'آراء<br>عن التقنية'],
    'отзывы<br>about the technology' => ['en' => 'reviews<br>of the technology', 'ar' => 'آراء<br>عن التقنية'],
    'Академик МААМ, генеральный директор «Регионального центра урбанистики»' => [
      'en' => 'Academician of MAAM, Director General of the Regional Centre of Urbanism',
      'ar' => 'أكاديمي في MAAM والمدير العام لمركز التخطيط الحضري الإقليمي',
    ],
    '«Значительная экономия бетона и металла... Очень гибкая система панелестроения, дающая возможности для архитекторов»' => [
      'en' => '“Significant savings of concrete and metal… A very flexible panel system that gives architects room to work.”',
      'ar' => '«توفير كبير في الخرسانة والمعدن... نظام ألواح مرن يمنح المعماريين إمكانيات واسعة»',
    ],
    'Академик IAA, вице-президент МААМ и СМА, лауреат премии «Хрустальный Дедал», «Золотое сечение». Проффесор МАРХИ' => [
      'en' => 'Academician of IAA, vice-president of MAAM and SMA, winner of the Crystal Daedalus and Golden Section prizes. Professor at MARCHI',
      'ar' => 'أكاديمي IAA ونائب رئيس MAAM وSMA، حائز على جائزة ديدالوس الكريستالي والقسم الذهبي. أستاذ في مارخي',
    ],
    '«Своя база, полный цикл, практически готовые изделия на выходе... Мне понравилась технология и гибкость системы, которая позволяет делать очень многое.»' => [
      'en' => '“Their own plant, a full cycle, almost finished products at the end… I liked the technology and the flexibility of the system, which allows a great deal.”',
      'ar' => '«قاعدة خاصة ودورة كاملة ومنتجات شبه جاهزة... أعجبتني التقنية ومرونة النظام التي تسمح بالكثير.»',
    ],
    'Главный редактор журнала «Архитектурный вестник», член-корреспондент МААМ, советник РААСН' => [
      'en' => 'Editor-in-chief of Architectural Herald, corresponding member of MAAM, adviser to RAASN',
      'ar' => 'رئيس تحرير مجلة النشرة المعمارية وعضو مراسل في MAAM ومستشار RAASN',
    ],
    '«Конструкция позволяет варьировать технологии отделки фасадов. Это может быть и планкер, и керамогранит, и другие панели... Это перспективная и любопытная вещь, которая помогает развивать архитектуру»' => [
      'en' => '“The structure lets you vary facade finishes. It can be planken, porcelain stoneware or other panels… A promising and interesting thing that helps architecture grow.”',
      'ar' => '«المنشأ يسمح بتنويع تشطيب الواجهات: بلانكن أو بورسلان أو ألواح أخرى... أمر واعد يساعد على تطوير العمارة»',
    ],
    'каталог домов <br><span>по технологии <br class="prem-br-tag"> бэнпан</span>' => [
      'en' => 'house catalog <br><span>using BENPAN <br class="prem-br-tag"> technology</span>',
      'ar' => 'كتالوج المنازل <br><span>بتقنية <br class="prem-br-tag"> بنبان</span>',
    ],
    'каталог домов' => ['en' => 'house catalog', 'ar' => 'كتالوج المنازل'],
    'по технологии' => ['en' => 'using the technology', 'ar' => 'بالتقنية'],
    'Дом Лот' => ['en' => 'House lot', 'ar' => 'منزل القطعة'],
    'Дом Lot' => ['en' => 'House lot', 'ar' => 'منزل القطعة'],
    'mortgage от' => ['en' => 'mortgage from', 'ar' => 'تمويل من'],
    'Информация о коттеджном поселке Берег Песочной в Подмосковье' => [
      'en' => 'About the Bereg Pesochnoy cottage village in the Moscow Region',
      'ar' => 'عن قرية بيريج بيسوتشنايا في ضواحي موسكو',
    ],
    'Информация о КП "Берег Песочной"' => ['en' => 'About the Bereg Pesochnoy village', 'ar' => 'عن قرية بيريج بيسوتشنايا'],
    'Информация о КП &quot;Берег Песочной&quot;' => ['en' => 'About the Bereg Pesochnoy village', 'ar' => 'عن قرية بيريج بيسوتشنايا'],
    'Information о Village "Bereg Pesochnoy"' => ['en' => 'About the Bereg Pesochnoy village', 'ar' => 'عن قرية بيريج بيسوتشنايا'],
    'Information о КП "Bereg Pesochnoy"' => ['en' => 'About the Bereg Pesochnoy village', 'ar' => 'عن قرية بيريج بيسوتشنايا'],
    'Жизнь на природе с городским комфортом' => ['en' => 'Life in nature with city comfort', 'ar' => 'حياة في الطبيعة براحة المدينة'],
    'Коттеджный поселок бизнес-класса «Берег Песочной» расположен в Истринском районе - одном из самых красивых и экологически чистых уголков Подмосковья, всего в 45 километрах от Москвы. Дом с участком в поселке – прекрасный способ уйти от городской суеты к размеренной жизни, чистой природе и здоровому образу жизни.' => [
      'en' => 'The Bereg Pesochnoy business-class cottage village is in the Istra district — one of the greenest corners of the Moscow Region, only 45 kilometres from Moscow. A house with a plot in the village is a way to leave city rush for a calmer life, clean nature and a healthier rhythm.',
      'ar' => 'تقع قرية بيريج بيسوتشنايا من فئة رجال الأعمال في منطقة إسترا، من أجمل وأنظف أنحاء ضواحي موسكو، على بعد 45 كم فقط من موسكو. منزل مع قطعة في القرية وسيلة لترك صخب المدينة لحياة أهدأ وطبيعة أنظف.',
    ],
    'Дом с участком в поселке' => ['en' => 'A house with a plot in the village', 'ar' => 'منزل مع قطعة في القرية'],
    'Дом с участком в village' => ['en' => 'A house with a plot in the village', 'ar' => 'منزل مع قطعة في القرية'],
    'Жилой комплекс как загородный квартал' => ['en' => 'The residential complex as a country quarter', 'ar' => 'المجمّع السكني كحي ريفي'],
    'Residential complex как загородный квартал' => ['en' => 'The residential complex as a country quarter', 'ar' => 'المجمّع السكني كحي ريفي'],
    'Жилой комплекс (ЖК) «Берег Песочной» — создан в форме загородного жилого квартала. Земля, на которой расположен поселок, относится к категории земель населенных пунктов. У каждого дома есть свой почтовый адрес, а жители ЖК могут воспользоваться правом прописки.' => [
      'en' => 'Bereg Pesochnoy was created as a country residential quarter. The land is classed as settlement land. Each house has its own postal address, and residents can register there.',
      'ar' => 'أُنشئ بيريج بيسوتشنايا كحي سكني ريفي. الأرض من فئة أراضي التجمعات. لكل منزل عنوان بريدي ويمكن للسكان التسجيل فيه.',
    ],
    'Управление ЖК осуществляется некоммерческим партнерством «Песочный берег».' => [
      'en' => 'The complex is managed by the Pesochny Bereg non-profit partnership.',
      'ar' => 'يدير المجمّع شراكة غير ربحية باسم بيريتشني بيريج.',
    ],
    'Планировка и инфраструктура поселка' => ['en' => 'Village layout and infrastructure', 'ar' => 'تخطيط القرية وبنيتها'],
    '«Берег Песочной» отличает изящество планировки, уникальный архитектурный стиль и продуманная инфраструктура, соответствующая современным мировым стандартам. Капитальные, энергоэффективные и экологически чистые дома построены по инновационной технологии проектирования и производства железобетонных конструкций для малоэтажного строительства БЭНПАН. Современные загородные коттеджи, таунхаусы позволяют выбрать жилье на любой вкус.' => [
      'en' => 'Bereg Pesochnoy stands out for an elegant layout, a unique architectural style and infrastructure that meets modern standards. Solid, energy-efficient and eco-friendly houses are built with the BENPAN technology. Modern country cottages and townhouses let you choose a home to taste.',
      'ar' => 'تميّز بيريج بيسوتشنايا أناقة التخطيط وأسلوب معماري فريد وبنية بمعايير حديثة. منازل متينة وموفرة مبنية بتقنية بنبان. كوتيدجات وتاون هاوس حديثة تتيح اختيار السكن.',
    ],
    'К каждому участку подведены все коммуникации необходимые для комфортного проживания. В поселке проложены кабельные электросети и установлена трансформаторная подстанция мощностью до 1000 кВт. Оптоволоконный кабель для подключения интернета заводится в дом. Вода в дом поступает по внутрипоселковому центральному водопроводу. ЖК подключен к магистральному газопроводу. Газовая сеть проходит по границе участка. Внутрипоселковая центральная канализация обеспечивает отвод от каждого дома и подключена к локальным очистным сооружениям. Тротуары и подъезды для автомобилей вымощены брусчаткой.' => [
      'en' => 'Every plot has the utilities needed for comfortable living. The village has cable power lines and a transformer station of up to 1,000 kW. Fibre is brought into the house. Water comes from the village mains. The estate is connected to the trunk gas line along the plot boundary. Central sewage from each house goes to local treatment plants. Sidewalks and driveways are paved with cobblestones.',
      'ar' => 'كل قطعة موصولة بالمرافق اللازمة. في القرية شبكة كهرباء ومحطة محولات حتى 1000 كيلوواط. الألياف تدخل المنزل. الماء من شبكة القرية. المجمّع موصول بالغاز الرئيسي على حدود القطعة. الصرف المركزي يتصل بمحطات معالجة محلية. الأرصفة والمداخل مبلطة.',
    ],
    'Вода в дом поступает по внутрипоселковому центральному водопроводу.' => [
      'en' => 'Water reaches the house through the village central water main.',
      'ar' => 'يصل الماء إلى المنزل عبر شبكة القرية المركزية.',
    ],
    'Water в дом поступает по внутрипоселковому центральному водопроводу.' => [
      'en' => 'Water reaches the house through the village central water main.',
      'ar' => 'يصل الماء إلى المنزل عبر شبكة القرية المركزية.',
    ],
    'Жизнь на природе' => ['en' => 'Life in nature', 'ar' => 'الحياة في الطبيعة'],
    'Жизнь in nature' => ['en' => 'Life in nature', 'ar' => 'الحياة في الطبيعة'],
    'Название жилого комплекса происходит от реки Песочная, которая протекает вдоль южного края поселка. Песочная — чистая, с пологими берегами и песчано-галечным дном, средняя глубина 1,2 метра. Водоем относится к первой рыбохозяйственной категории, в нем водится окунь, лещ, карась, щука.' => [
      'en' => 'The name comes from the Pesochnaya river that runs along the southern edge of the village. It is clean, with gentle banks and a sand-and-gravel bed, about 1.2 metres deep. The water is a first-category fishery: perch, bream, crucian carp and pike live here.',
      'ar' => 'الاسم من نهر بيسوتشنايا الذي يجري على الحافة الجنوبية. النهر نظيف بضفاف لطيفة وقاع رملي حصوي وعمق نحو 1.2 م. المياه من الفئة الأولى وفيها فرخ وسمك الج multim وكارس وبايك.',
    ],
    'К границе поселка примыкает смешанный лес, переходящий в парковую территорию. Общая площадь парка составляет более 7 гектаров. Он разбит на несколько зон: каштановые, липовые и кленовые аллеи, фруктовый сад с яблонями и вишней, прогулочная зона, пруд и живой уголок. Около пруда, рядом с пляжем, расположен облагороженный старинный источник. В нескольких минутах езды от поселка находится Истринское водохранилище.' => [
      'en' => 'A mixed forest meets the village boundary and turns into parkland. The park is more than 7 hectares, with chestnut, linden and maple alleys, an apple and cherry orchard, a walking area, a pond and a wildlife corner. By the pond, next to the beach, there is a restored old spring. The Istra reservoir is a few minutes’ drive away.',
      'ar' => 'غابة مختلطة تلامس حدود القرية وتتحول إلى حديقة. الحديقة أكثر من 7 هكتارات: أزقة كستناء وزيزفون وأسفندان وبستان تفاح وكرز ومنطقة تنزه وبركة وركن حي. بجانب البركة نبع قديم مُعتنى به. خزان إسترا على بعد دقائق بالسيارة.',
    ],
    'Общая площадь парка составляет более 7 гектаров.' => [
      'en' => 'The total park area is more than 7 hectares.',
      'ar' => 'تبلغ مساحة الحديقة أكثر من 7 هكتارات.',
    ],
    'Общая area парка составляет более 7 гектаров.' => [
      'en' => 'The total park area is more than 7 hectares.',
      'ar' => 'تبلغ مساحة الحديقة أكثر من 7 هكتارات.',
    ],
    'Истринское водохранилище' => ['en' => 'Istra reservoir', 'ar' => 'خزان إسترا'],
    'В парке, на общественных и частных пространствах жилого комплекса высажено более 4000 деревьев и кустарников. Каждый год количество саженцев увеличивается, в т.ч. при активном участии жителей.' => [
      'en' => 'More than 4,000 trees and shrubs have been planted in the park and on public and private grounds. The number of saplings grows every year, including with the help of residents.',
      'ar' => 'زُرع أكثر من 4000 شجرة وشجيرة في الحديقة وفي المساحات العامة والخاصة. يزداد عدد الشتلات كل عام بمشاركة السكان.',
    ],
    'более 4000 деревьев' => ['en' => 'more than 4,000 trees', 'ar' => 'أكثر من 4000 شجرة'],
    'более 4000 trees' => ['en' => 'more than 4,000 trees', 'ar' => 'أكثر من 4000 شجرة'],
    'В ЖК «Берег Песочной» предусмотрено множество площадок для активного отдыха и занятий спортом на природе - открытый теннисный корт, футбольная и волейбольная площадки, тренажеры для занятий на свежем воздухе (воркаут). Зимой в парке прокладываются дорожки для лыжников.' => [
      'en' => 'Bereg Pesochnoy has many spots for outdoor sport: an open tennis court, football and volleyball grounds, and workout machines. In winter ski tracks are laid in the park.',
      'ar' => 'في بيريج بيسوتشنايا ساحات كثيرة للرياضة: ملعب تنس مكشوف وكرة قدم وطائرة وأجهزة تمرين. في الشتاء تُمد مسارات تزلج في الحديقة.',
    ],
    'занятий спортом на природе' => ['en' => 'outdoor sports', 'ar' => 'رياضة في الطبيعة'],
    'занятий спортом in nature' => ['en' => 'outdoor sports', 'ar' => 'رياضة في الطبيعة'],
    'Комфорт и безопасность жителей – главные приоритеты в ЖК «Берег Песочной». В случае отключения электроэнергии автоматически подключается газогенераторная подстанция, которая обеспечивает освещение жилого комплекса и работу водозаборного узла.' => [
      'en' => 'Residents’ comfort and safety are the top priorities at Bereg Pesochnoy. If the power goes out, a gas-generator station switches on automatically and keeps the lighting and the water intake running.',
      'ar' => 'راحة السكان وأمانهم أولوية في بيريج بيسوتشنايا. عند انقطاع الكهرباء تعمل محطة مولد غاز تلقائياً وتغذي الإنارة ومحطة المياه.',
    ],
    'Безопасность жителей и гостей поселка обеспечивает огороженный периметр, въездная группа с шлагбаумом, круглосуточная охрана и система видеонаблюдения за общественными пространствами и гостевой парковкой.' => [
      'en' => 'A fenced perimeter, a gated entrance, 24/7 security and CCTV over public spaces and guest parking keep residents and guests safe.',
      'ar' => 'محيط مسيّج ومدخل بحاجز وحراسة على مدار الساعة وكاميرات على المساحات العامة وموقف الضيوف تحمي السكان والزوّار.',
    ],
    'круглосуточная охрана' => ['en' => '24/7 security', 'ar' => 'حراسة على مدار الساعة'],
    'КП «Берег Песочной» завтра' => ['en' => 'Bereg Pesochnoy tomorrow', 'ar' => 'بيريج بيسوتشنايا غداً'],
    'Village «Bereg Pesochnoy» завтра' => ['en' => 'Bereg Pesochnoy tomorrow', 'ar' => 'بيريج بيسوتشنايا غداً'],
    'В современном административно-бытовом комплексе на территории жилого комплекса планируется разместить службу сервиса, где можно будет заказать прачечные услуги, уборку дома, озеленение участка и заказ еды на дом из кафе и мини-маркета. Скоро появится, аптека, кафе и детская игровая комната, салон красоты и фитнес-клуб с массажным центром, джакузи, сауной и хаммамом, конференц-зал — кинотеатр.' => [
      'en' => 'A service desk is planned in the admin building: laundry, house cleaning, garden work and food delivery from the cafe and mini-market. A pharmacy, cafe, kids’ playroom, beauty salon and a fitness club with a massage centre, jacuzzi, sauna, hammam and a conference hall–cinema will follow.',
      'ar' => 'سيُفتح مكتب خدمات في المبنى الإداري: غسيل وتنظيف وحدائق وطلب طعام من المقهى والمتجر. لاحقاً صيدلية ومقهى وغرفة أطفال وصالون ونادٍ رياضي مع مساج وجاكوزي وساونا وحمام وقاعة–سينما.',
    ],
    'Развитию пляжной территории поселка уделяется большое внимание. Скоро появится лодочная станция для водных прогулок по реке Песочная и понтонный пляж с комфортным доступом к воде.' => [
      'en' => 'The beach area is a priority. A boat station for trips on the Pesochnaya and a pontoon beach with easy access to the water will appear soon.',
      'ar' => 'يُولى شاطئ القرية اهتماماً كبيراً. قريباً محطة قوارب لنزهات نهر بيسوتشنايا وشاطئ عائم بوصول مريح إلى الماء.',
    ],
    'почему выгодно выбрать' => ['en' => 'why it pays to choose', 'ar' => 'لماذا يستحق الاختيار'],
    'котеджный поселок' => ['en' => 'the cottage village', 'ar' => 'قرية الكوتيدجات'],
    '8 га парков' => ['en' => '8 ha of parks', 'ar' => '8 هكتارات من الحدائق'],
    'Экологически чистый<br>район на Новорижском шоссе' => [
      'en' => 'A green district<br>on Novorizhskoye highway',
      'ar' => 'منطقة نظيفة<br>على طريق نوفوريجسكوي',
    ],
    'городские<br>коммуникации<br>на участке' => ['en' => 'city utilities<br>on the plot', 'ar' => 'مرافق المدينة<br>على القطعة'],
    'интернет<br>по оптоволокну' => ['en' => 'fibre<br>internet', 'ar' => 'إنترنت<br>بالألياف'],
    'истринское<br>водохранилище' => ['en' => 'Istra<br>reservoir', 'ar' => 'خزان<br>إسترا'],
    'Поселок обжит, первая <br>очередь сдана и заселена' => [
      'en' => 'The village is lived in: the first<br>phase is completed and occupied',
      'ar' => 'القرية مأهولة: المرحلة الأولى<br>مسلَّمة ومسكونة',
    ],
    'Village обжит, первая' => ['en' => 'The village is lived in: the first', 'ar' => 'القرية مأهولة: المرحلة الأولى'],
    'очередь сдана и заселена' => ['en' => 'phase is completed and occupied', 'ar' => 'مسلَّمة ومسكونة'],
    'Поселок бизнес-класса в<br>Истринском районе Подмосковья' => [
      'en' => 'A business-class village in<br>the Istra district of the Moscow Region',
      'ar' => 'قرية من فئة رجال الأعمال<br>في منطقة إسترا بضواحي موسكو',
    ],
    'Village бизнес-класса в' => ['en' => 'A business-class village in', 'ar' => 'قرية من فئة رجال الأعمال في'],
    '50 минут<br>от мкад' => ['en' => '50 minutes<br>from MKAD', 'ar' => '50 دقيقة<br>من الطريق الدائري'],
    'Безопасная<br>территория<br>поселка' => ['en' => 'A safe<br>village<br>territory', 'ar' => 'أرض<br>آمنة<br>للقرية'],
    'Быстро развивающаяся<br>собственная<br>инфраструктура' => [
      'en' => 'Fast-growing<br>own<br>infrastructure',
      'ar' => 'بنية خاصة<br>سريعة<br>التطور',
    ],
    'от МКАд по<br>новорижскому шоссе' => ['en' => 'from MKAD via<br>Novorizhskoye highway', 'ar' => 'من الطريق الدائري عبر<br>نوفوريجسكوي'],
    'В 10 минутах езды<br>от г. истра на машине' => ['en' => 'A 10-minute drive<br>from Istra', 'ar' => '10 دقائق بالسيارة<br>من إسترا'],
    'Централизованное энергоснабжение, магистральный газ, собственный водозаборный узел, централизованная канализация, оптоволоконный интернет' => [
      'en' => 'Central power, trunk gas, our own water intake, central sewage, fibre internet',
      'ar' => 'كهرباء مركزية وغاز رئيسي ومحطة مياه خاصة وصرف مركزي وإنترنت بالألياف',
    ],
    'Транспортная доступность' => ['en' => 'Transport access', 'ar' => 'سهولة الوصول'],
    'В 10 минутах езды на автомобиле находятся магазины, детские сады и школы, спортивные комплексы, детские и взрослые поликлиники города Истра. Автобусная остановка расположена в шаговой доступности от поселка.' => [
      'en' => 'Shops, kindergartens and schools, sports centres and clinics of Istra are a 10-minute drive away. A bus stop is a short walk from the village.',
      'ar' => 'المتاجر ورياض الأطفال والمدارس والمراكز الرياضية وعيادات إسترا على بعد 10 دقائق بالسيارة. محطة الحافلات على مسافة قريبة سيراً.',
    ],
    'Мы заботимся о безопасности жителей, поэтому наш поселок представляет собой охраняемую, закрытую от посторонних людей территорию, в поселке круглосуточно работает видеонаблюдение. Сотрудники центрального пункта охраны следят за порядком, обеспечивают покой и безопасность.' => [
      'en' => 'We look after residents’ safety: the village is a guarded, closed territory with CCTV around the clock. Officers at the central security post keep order and peace.',
      'ar' => 'نهتم بأمان السكان: القرية منطقة محروسة مغلقة وكاميرات على مدار الساعة. موظفو نقطة الحراسة المركزية يحفظون النظام والهدوء.',
    ],
    'в поселке круглосуточно работает видеонаблюдение' => [
      'en' => 'CCTV works around the clock in the village',
      'ar' => 'الكاميرات تعمل على مدار الساعة في القرية',
    ],
    'в village круглосуточно работает видеонаблюдение' => [
      'en' => 'CCTV works around the clock in the village',
      'ar' => 'الكاميرات تعمل على مدار الساعة في القرية',
    ],
    'Благоустроенный ландшафтный парк площадью 8 гектаров с более чем 4000 деревьев, благоустроенный ландшафтный парк площадью 8 гектаров, высажено более 4000 деревьев, каштаны, липы, клены, фруктовый сад с яблонями и вишней. Украшением парка является пруд с фонтаном. Для удобства жителей обустроены освещенные пешеходные и велосипедные дорожки, зона для барбекю и живописный сад камней.' => [
      'en' => 'A landscaped 8-hectare park with more than 4,000 trees: chestnuts, lindens, maples, an apple and cherry orchard. A fountain pond is the park’s centrepiece. There are lit walking and cycling paths, a barbecue area and a rock garden.',
      'ar' => 'حديقة مناظر 8 هكتارات بأكثر من 4000 شجرة: كستناء وزيزفون وأسفندان وبستان تفاح وكرز. بركة بنافورة تزيّن الحديقة. مسارات مشي ودراجات مضاءة ومنطقة شواء وحديقة صخور.',
    ],
    'Дорожная сеть' => ['en' => 'Road network', 'ar' => 'شبكة الطرق'],
    'Для комфортного проезда жителей, их гостей и служб доставки все дороги и просторные парковочные зоны на территории поселка выполнены из качественной брусчатки.' => [
      'en' => 'For comfortable driving by residents, guests and delivery services, all roads and spacious parking areas are made of quality cobblestones.',
      'ar' => 'لراحة مرور السكان والضيوف والتوصيل، كل الطرق ومواقف السيارات الواسعة من بلاط عالي الجودة.',
    ],
    'Спорт и развлечения' => ['en' => 'Sports and leisure', 'ar' => 'رياضة وترفيه'],
    'Sports и развлечения' => ['en' => 'Sports and leisure', 'ar' => 'رياضة وترفيه'],
    'Обустроены площадки для уличной гимнастики (воркаут), футбола и волейбола. В досуговой зоне можно поиграть в настольный теннис, бильярд и шахматы.' => [
      'en' => 'There are workout, football and volleyball grounds. In the leisure area you can play table tennis, billiards and chess.',
      'ar' => 'هناك ساحات تمارين وكرة قدم وطائرة. في منطقة الترفيه تنس طاولة وبلياردو وشطرنج.',
    ],
    'Служба эксплуатации' => ['en' => 'Maintenance service', 'ar' => 'خدمة التشغيل'],
    'В поселке действует служба эксплуатации, которая заботится о комфортной жизни жителей поселка.' => [
      'en' => 'A maintenance service in the village looks after residents’ everyday comfort.',
      'ar' => 'تعمل في القرية خدمة تشغيل تهتم براحة السكان.',
    ],
    'В village действует служба эксплуатации, которая заботится о комфортной жизни жителей поселка.' => [
      'en' => 'A maintenance service in the village looks after residents’ everyday comfort.',
      'ar' => 'تعمل في القرية خدمة تشغيل تهتم براحة السكان.',
    ],
    'От других коттеджных поселков «Берег Песочной» отличает изящество планировки, единый архитектурный стиль и продуманная инфраструктура, соответствующая самым современным стандартам. К каждому участку подведены все коммуникации: центральное водоснабжение, канализация, электричество, газ, а также оптоволоконный интернет и кабельное телевидение.' => [
      'en' => 'Bereg Pesochnoy stands out from other cottage villages with an elegant layout, a single architectural style and infrastructure that meets current standards. Every plot has water, sewage, power, gas, fibre internet and cable TV.',
      'ar' => 'تميّز بيريج بيسوتشنايا عن غيرها بأناقة التخطيط وأسلوب معماري موحّد وبنية حديثة. كل قطعة موصولة بالماء والصرف والكهرباء والغاز والإنترنت بالألياف والتلفزيون.',
    ],
    'Шахматный клуб' => ['en' => 'Chess club', 'ar' => 'نادي شطرنج'],
    'Для ценителей большой игры' => ['en' => 'For fans of the great game', 'ar' => 'لعشاق اللعبة الكبرى'],
    'Волейбольная площадка' => ['en' => 'Volleyball court', 'ar' => 'ملعب طائرة'],
    'Наслаждайтесь игрой на большой игровой площадке' => ['en' => 'Enjoy the game on a large court', 'ar' => 'استمتعوا باللعب في ملعب واسع'],
    'Бильярд' => ['en' => 'Billiards', 'ar' => 'بلياردو'],
    'Возможность здорово провести время' => ['en' => 'A good way to spend time', 'ar' => 'فرصة لقضاء وقت ممتع'],
    '&quot;КП Берег Песочной - территория 28 га, 8 га парков, городские коммуникации на участке, первая очередь сдана и заселена, рядом водохранилище&quot;' => [
      'en' => '&quot;Bereg Pesochnoy — 28 ha of land, 8 ha of parks, city utilities on the plot, the first phase completed and occupied, a reservoir nearby&quot;',
      'ar' => '&quot;بيريج بيسوتشنايا — 28 هكتاراً و8 هكتارات حدائق ومرافق المدينة على القطعة والمرحلة الأولى مسلَّمة ومسكونة وخزان قريب&quot;',
    ],
    '"КП Берег Песочной - территория 28 га, 8 га парков, городские коммуникации на участке, первая очередь сдана и заселена, рядом водохранилище"' => [
