    '1. Общие положения' => ['en' => '1. General provisions', 'ar' => '1. أحكام عامة'],
    '2. Основные понятия, используемые в Политике' => ['en' => '2. Main terms used in this Policy', 'ar' => '2. المصطلحات الأساسية في السياسة'],
    '3. Оператор может обрабатывать следующие персональные данные Пользователя' => [
      'en' => '3. The Operator may process the following personal data of the User',
      'ar' => '3. يجوز للمشغّل معالجة البيانات الشخصية التالية للمستخدم',
    ],
    '4. Цели обработки персональных данных' => ['en' => '4. Purposes of personal data processing', 'ar' => '4. أغراض معالجة البيانات الشخصية'],
    '4. Цели обработки personal data' => ['en' => '4. Purposes of personal data processing', 'ar' => '4. أغراض معالجة البيانات الشخصية'],
    '5. Правовые основания обработки персональных данных' => ['en' => '5. Legal grounds for personal data processing', 'ar' => '5. الأسس القانونية لمعالجة البيانات الشخصية'],
    '5. Правовые основания обработки personal data' => ['en' => '5. Legal grounds for personal data processing', 'ar' => '5. الأسس القانونية لمعالجة البيانات الشخصية'],
    '6. Порядок сбора, хранения, передачи и других видов обработки персональных данных' => [
      'en' => '6. Collection, storage, transfer and other processing of personal data',
      'ar' => '6. جمع البيانات الشخصية وتخزينها ونقلها ومعالجتها',
    ],
    '6. Порядок сбора, хранения, передачи и других видов обработки personal data' => [
      'en' => '6. Collection, storage, transfer and other processing of personal data',
      'ar' => '6. جمع البيانات الشخصية وتخزينها ونقلها ومعالجتها',
    ],
    '7. Трансграничная передача персональных данных' => ['en' => '7. Cross-border transfer of personal data', 'ar' => '7. نقل البيانات الشخصية عبر الحدود'],
    '7. Трансграничная передача personal data' => ['en' => '7. Cross-border transfer of personal data', 'ar' => '7. نقل البيانات الشخصية عبر الحدود'],
    '8. Заключительные положения' => ['en' => '8. Final provisions', 'ar' => '8. أحكام ختامية'],
    'Настоящая политика обработки персональных данных составлена в соответствии с требованиями Федерального закона от 27.07.2006. №152-ФЗ «О персональных данных» и определяет порядок обработки персональных данных и меры по обеспечению безопасности персональных данных ООО "Агроком" (далее – Оператор).' => [
      'en' => 'This personal data processing policy is drafted in line with Federal Law No. 152-FZ of 27 July 2006 “On Personal Data” and sets out how Agrokom LLC (the Operator) processes personal data and protects it.',
      'ar' => 'وُضعت سياسة معالجة البيانات الشخصية وفق القانون الاتحادي رقم 152-FZ بتاريخ 27 يوليو 2006 «حول البيانات الشخصية» وتحدّد كيف تعالج شركة أغرُكوم (المشغّل) البيانات وتحميها.',
    ],
    'Оператор ставит своей важнейшей целью и условием осуществления своей деятельности соблюдение прав и свобод человека и гражданина при обработке его персональных данных, в том числе защиты прав на неприкосновенность частной жизни, личную и семейную тайну.' => [
      'en' => 'The Operator’s main aim is to respect human and civil rights and freedoms when processing personal data, including the right to privacy and to personal and family secrets.',
      'ar' => 'هدف المشغّل الأساسي احترام حقوق الإنسان والحريات عند معالجة البيانات الشخصية، بما في ذلك حرمة الحياة الخاصة والسر الشخصي والعائلي.',
    ],
    'Настоящая политика Оператора в отношении обработки персональных данных (далее – Политика) применяется ко всей информации, которую Оператор может получить о посетителях веб-сайта' => [
      'en' => 'This Operator policy on personal data processing (the Policy) applies to all information the Operator may obtain about visitors of the website',
      'ar' => 'تنطبق سياسة المشغّل لمعالجة البيانات الشخصية (السياسة) على كل المعلومات التي قد يحصل عليها المشغّل عن زوار الموقع',
    ],
    'Автоматизированная обработка персональных данных – обработка персональных данных с помощью средств вычислительной техники;' => [
      'en' => 'Automated processing of personal data — processing of personal data with computing equipment;',
      'ar' => 'المعالجة الآلية للبيانات الشخصية — معالجتها بوسائل الحاسوب؛',
    ],
    'Блокирование персональных данных – временное прекращение обработки персональных данных (за исключением случаев, если обработка необходима для уточнения персональных данных);' => [
      'en' => 'Blocking of personal data — a temporary stop of processing (except where processing is needed to clarify the data);',
      'ar' => 'حجب البيانات الشخصية — وقف مؤقت للمعالجة (إلا إذا لزم الأمر لتوضيح البيانات)؛',
    ],
    'Веб-сайт – совокупность графических и информационных материалов, а также программ для ЭВМ и баз данных, обеспечивающих их доступность в сети интернет по сетевому адресу' => [
      'en' => 'Website — the graphic and information materials, software and databases that make them available on the internet at',
      'ar' => 'الموقع — المواد الرسومية والمعلوماتية والبرامج وقواعد البيانات التي تتيحها على الإنترنت على العنوان',
    ],
    'Информационная система персональных данных — совокупность содержащихся в базах данных персональных данных, и обеспечивающих их обработку информационных технологий и технических средств;' => [
      'en' => 'Personal data information system — the personal data in databases together with the IT and technical means that process it;',
      'ar' => 'نظام معلومات البيانات الشخصية — البيانات في القواعد مع التقنيات والوسائل التي تعالجها؛',
    ],
    'Обезличивание персональных данных — действия, в результате которых невозможно определить без использования дополнительной информации принадлежность персональных данных конкретному Пользователю или иному субъекту персональных данных;' => [
      'en' => 'Anonymisation of personal data — actions after which the data cannot be linked to a specific User or other data subject without extra information;',
      'ar' => 'إخفاء هوية البيانات — إجراءات تجعل تعذر ربط البيانات بمستخدم معيّن دون معلومات إضافية؛',
    ],
    'Обработка персональных данных – любое действие (операция) или совокупность действий (операций), совершаемых с использованием средств автоматизации или без использования таких средств с персональными данными, включая сбор, запись, систематизацию, накопление, хранение, уточнение (обновление, изменение), извлечение, использование, передачу (распространение, предоставление, доступ), обезличивание, блокирование, удаление, уничтожение персональных данных;' => [
      'en' => 'Processing of personal data — any operation or set of operations on personal data, automated or not, including collection, recording, organisation, accumulation, storage, updating, retrieval, use, transfer (dissemination, provision, access), anonymisation, blocking, deletion and destruction;',
      'ar' => 'معالجة البيانات الشخصية — أي عملية على البيانات، آلية أو يدوية، بما في ذلك الجمع والتسجيل والتنظيم والتخزين والتحديث والاستخراج والاستخدام والنقل والإخفاء والحجب والحذف والإتلاف؛',
    ],
    'Оператор – государственный орган, муниципальный орган, юридическое или физическое лицо, самостоятельно или совместно с другими лицами организующие и (или) осуществляющие обработку персональных данных, а также определяющие цели обработки персональных данных, состав персональных данных, подлежащих обработке, действия (операции), совершаемые с персональными данными;' => [
      'en' => 'Operator — a public body, municipality, legal entity or individual that organises and/or carries out personal data processing, alone or with others, and that defines the purposes, the data to be processed and the operations performed;',
      'ar' => 'المشغّل — جهة عامة أو بلدية أو شخص اعتباري أو طبيعي ينظّم و/أو ينفّذ معالجة البيانات ويحدّد أغراضها والبيانات الخاضعة لها والعمليات عليها؛',
    ],
    'Персональные данные – любая информация, относящаяся прямо или косвенно к определенному или определяемому Пользователю веб-сайта' => [
      'en' => 'Personal data — any information that relates, directly or indirectly, to an identified or identifiable User of the website',
      'ar' => 'البيانات الشخصية — أي معلومات تتعلق مباشرة أو غير مباشرة بمستخدم محدّد أو قابل للتحديد للموقع',
    ],
    'Пользователь – любой посетитель веб-сайта' => ['en' => 'User — any visitor of the website', 'ar' => 'المستخدم — أي زائر للموقع'],
    'Предоставление персональных данных – действия, направленные на раскрытие персональных данных определенному лицу или определенному кругу лиц;' => [
      'en' => 'Provision of personal data — actions aimed at disclosing personal data to a specific person or a defined group of persons;',
      'ar' => 'تقديم البيانات الشخصية — إجراءات لكشف البيانات لشخص معيّن أو دائرة محدّدة؛',
    ],
    'Распространение персональных данных – любые действия, направленные на раскрытие персональных данных неопределенному кругу лиц (передача персональных данных) или на ознакомление с персональными данными неограниченного круга лиц, в том числе обнародование персональных данных в средствах массовой информации, размещение в информационно-телекоммуникационных сетях или предоставление доступа к персональным данным каким-либо иным способом;' => [
      'en' => 'Dissemination of personal data — any actions aimed at disclosing personal data to an undefined circle of persons, including publication in the media, posting on networks or otherwise granting access;',
      'ar' => 'نشر البيانات الشخصية — أي إجراءات لكشف البيانات لدائرة غير محدّدة، بما في ذلك النشر في الإعلام أو على الشبكات أو إتاحة الوصول بأي طريقة أخرى؛',
    ],
    'Трансграничная передача персональных данных – передача персональных данных на территорию иностранного государства органу власти иностранного государства, иностранному физическому или иностранному юридическому лицу;' => [
      'en' => 'Cross-border transfer of personal data — transfer of personal data to the territory of a foreign state, to a foreign authority, or to a foreign individual or legal entity;',
      'ar' => 'النقل عبر الحدود — نقل البيانات إلى أراضي دولة أجنبية أو إلى سلطة أو شخص أجنبي؛',
    ],
    'Уничтожение персональных данных – любые действия, в результате которых персональные данные уничтожаются безвозвратно с невозможностью дальнейшего восстановления содержания персональных данных в информационной системе персональных данных и (или) результате которых уничтожаются материальные носители персональных данных.' => [
      'en' => 'Destruction of personal data — any actions that permanently destroy personal data so that it cannot be restored in the information system and/or that destroy the physical media holding the data.',
      'ar' => 'إتلاف البيانات الشخصية — أي إجراءات تُتلف البيانات نهائياً بحيث يتعذّر استعادتها و/أو تُتلف الوسائط المادية.',
    ],
    'Фамилия, имя, отчество;' => ['en' => 'Last name, first name, patronymic;', 'ar' => 'الاسم الكامل؛'],
    'Электронный адрес;' => ['en' => 'Email address;', 'ar' => 'البريد الإلكتروني؛'],
    'Номера телефонов;' => ['en' => 'Phone numbers;', 'ar' => 'أرقام الهواتف؛'],
    'Также на сайте происходит сбор и обработка обезличенных данных о посетителях (в т.ч. файлов «cookie») с помощью сервисов интернет-статистики (Яндекс Метрика и Гугл Аналитика и других).' => [
      'en' => 'The site also collects and processes anonymised visitor data (including cookies) via internet statistics services (Yandex Metrica, Google Analytics and others).',
      'ar' => 'يجمع الموقع أيضاً بيانات مجهولة عن الزوار (بما في ذلك ملفات تعريف الارتباط) عبر خدمات الإحصاء (ياندكس متريكا وغوغل أناليتكس وغيرها).',
    ],
    'Вышеперечисленные данные далее по тексту Политики объединены общим понятием Персональные данные.' => [
      'en' => 'The data listed above are referred to in this Policy as Personal data.',
      'ar' => 'البيانات أعلاه تُسمّى في هذه السياسة البيانات الشخصية.',
    ],
    'Цель обработки персональных данных Пользователя — заключение, исполнение и прекращение гражданско-правовых договоров; предоставление доступа Пользователю к сервисам, информации и/или материалам, содержащимся на веб-сайте' => [
      'en' => 'The purpose of processing the User’s personal data is to conclude, perform and terminate civil-law contracts; to give the User access to services, information and/or materials on the website',
      'ar' => 'غرض معالجة بيانات المستخدم إبرام العقود المدنية وتنفيذها وإنهاؤها؛ وإتاحة الخدمات والمعلومات و/أو المواد على الموقع',
    ],
    'уточнение деталей заказа.' => ['en' => 'clarifying order details.', 'ar' => 'توضيح تفاصيل الطلب.'],
    'Также Оператор имеет право направлять Пользователю уведомления о новых продуктах и услугах, специальных предложениях и различных событиях. Пользователь всегда может отказаться от получения информационных сообщений, направив Оператору письмо на адрес электронной почты' => [
      'en' => 'The Operator may also send the User notices about new products and services, special offers and events. The User may opt out at any time by emailing the Operator at',
      'ar' => 'يجوز للمشغّل أيضاً إرسال إشعارات عن منتجات وخدمات وعروض وفعاليات. يمكن للمستخدم إلغاء ذلك بمراسلة المشغّل على',
    ],
    'с пометкой «Отказ от уведомлениях о новых продуктах и услугах и специальных предложениях».' => [
      'en' => 'marked “Opt-out of notices about new products, services and special offers”.',
      'ar' => 'مع التأشير «إلغاء الإشعارات عن المنتجات والخدمات والعروض».',
    ],
    'Обезличенные данные Пользователей, собираемые с помощью сервисов интернет-статистики, служат для сбора информации о действиях Пользователей на сайте, улучшения качества сайта и его содержания.' => [
      'en' => 'Anonymised User data collected via statistics services is used to learn how Users act on the site and to improve the site and its content.',
      'ar' => 'البيانات المجهولة التي تُجمع عبر الإحصاء تُستخدم لمعرفة سلوك المستخدمين وتحسين الموقع ومحتواه.',
    ],
    'Оператор обрабатывает персональные данные Пользователя только в случае их заполнения и/или отправки Пользователем самостоятельно через специальные формы, расположенные на сайте' => [
      'en' => 'The Operator processes the User’s personal data only if the User fills in and/or submits them through the forms on the website',
      'ar' => 'يعالج المشغّل بيانات المستخدم فقط إذا ملأها و/أو أرسلها بنفسه عبر النماذج في الموقع',
    ],
    'Заполняя соответствующие формы и/или отправляя свои персональные данные Оператору, Пользователь выражает свое согласие с данной Политикой.' => [
      'en' => 'By filling in the forms and/or sending personal data to the Operator, the User agrees to this Policy.',
      'ar' => 'بملء النماذج و/أو إرسال البيانات إلى المشغّل يوافق المستخدم على هذه السياسة.',
    ],
    'Оператор обрабатывает обезличенные данные о Пользователе в случае, если это разрешено в настройках браузера Пользователя (включено сохранение файлов «cookie» и использование технологии JavaScript).' => [
      'en' => 'The Operator processes anonymised User data if the User’s browser settings allow it (cookies and JavaScript are enabled).',
      'ar' => 'يعالج المشغّل البيانات المجهولة إذا سمحت إعدادات متصفح المستخدم (تفعيل ملفات تعريف الارتباط وجافاسكربت).',
    ],
    'Безопасность персональных данных, которые обрабатываются Оператором, обеспечивается путем реализации правовых, организационных и технических мер, необходимых для выполнения в полном объеме требований действующего законодательства в области защиты персональных данных.' => [
      'en' => 'The security of personal data processed by the Operator is ensured by legal, organisational and technical measures required to meet personal-data protection law in full.',
      'ar' => 'يُؤمَّن أمان البيانات التي يعالجها المشغّل بإجراءات قانونية وتنظيمية وتقنية تستوفي قانون حماية البيانات.',
    ],
    'Оператор обеспечивает сохранность персональных данных и принимает все возможные меры, исключающие доступ к персональным данным неуполномоченных лиц.' => [
      'en' => 'The Operator keeps personal data safe and takes all possible measures to prevent access by unauthorised persons.',
      'ar' => 'يحفظ المشغّل البيانات ويتخذ كل التدابير الممكنة لمنع وصول غير المصرّح لهم.',
    ],
    'Персональные данные Пользователя никогда, ни при каких условиях не будут переданы третьим лицам, за исключением случаев, связанных с исполнением действующего законодательства.' => [
      'en' => 'The User’s personal data will never be transferred to third parties except where required by applicable law.',
      'ar' => 'لن تُنقل بيانات المستخدم إلى أطراف ثالثة إلا حيث يقتضي القانون النافذ.',
    ],
    'В случае выявления неточностей в персональных данных, Пользователь может актуализировать их самостоятельно, путем направления Оператору уведомление на адрес электронной почты Оператора' => [
      'en' => 'If the User finds inaccuracies in the personal data, they may update them by sending a notice to the Operator’s email',
      'ar' => 'إذا وجد المستخدم عدم دقة في البيانات يمكنه تحديثها بإشعار إلى بريد المشغّل',
    ],
    'с пометкой «Актуализация персональных данных».' => [
      'en' => 'marked “Update of personal data”.',
      'ar' => 'مع التأشير «تحديث البيانات الشخصية».',
    ],
    'Срок обработки персональных данных является неограниченным. Пользователь может в любой момент отозвать свое согласие на обработку персональных данных, направив Оператору уведомление посредством электронной почты на электронный адрес Оператора' => [
      'en' => 'Personal data is processed for an unlimited term. The User may withdraw consent at any time by emailing the Operator at',
      'ar' => 'مدة المعالجة غير محدودة. يمكن للمستخدم سحب الموافقة في أي وقت بمراسلة المشغّل على',
    ],
    'с пометкой «Отзыв согласия на обработку персональных данных».' => [
      'en' => 'marked “Withdrawal of consent to personal data processing”.',
      'ar' => 'مع التأشير «سحب الموافقة على معالجة البيانات الشخصية».',
    ],
    'Оператор до начала осуществления трансграничной передачи персональных данных обязан убедиться в том, что иностранным государством, на территорию которого предполагается осуществлять передачу персональных данных, обеспечивается надежная защита прав субъектов персональных данных.' => [
      'en' => 'Before a cross-border transfer the Operator must make sure that the foreign state provides reliable protection of data subjects’ rights.',
      'ar' => 'قبل النقل عبر الحدود يجب على المشغّل التأكد من أن الدولة الأجنبية توفر حماية موثوقة لحقوق أصحاب البيانات.',
    ],
    'Трансграничная передача персональных данных на территории иностранных государств, не отвечающих вышеуказанным требованиям, может осуществляться только в случае наличия согласия в письменной форме субъекта персональных данных на трансграничную передачу его персональных данных и/или исполнения договора, стороной которого является субъект персональных данных.' => [
      'en' => 'A cross-border transfer to a state that does not meet those requirements may take place only with the data subject’s written consent and/or to perform a contract to which the data subject is a party.',
      'ar' => 'لا يجوز النقل إلى دولة لا تستوفي تلك المتطلبات إلا بموافقة كتابية من صاحب البيانات و/أو لتنفيذ عقد هو طرف فيه.',
    ],
    'Пользователь может получить любые разъяснения по интересующим вопросам, касающимся обработки его персональных данных, обратившись к Оператору с помощью электронной почты' => [
      'en' => 'The User may obtain any clarification about the processing of their personal data by emailing the Operator at',
      'ar' => 'يمكن للمستخدم الحصول على أي توضيح حول معالجة بياناته بمراسلة المشغّل على',
    ],
    'В данном документе будут отражены любые изменения политики обработки персональных данных Оператором. Политика действует бессрочно до замены ее новой версией.' => [
      'en' => 'Any changes to the Operator’s personal data policy will be reflected in this document. The Policy remains in force until replaced by a new version.',
      'ar' => 'ستظهر أي تغييرات على سياسة المشغّل في هذا المستند. تسري السياسة بلا أجل حتى تحل محلها نسخة جديدة.',
    ],
    'Актуальная версия Политики в свободном доступе расположена в сети Интернет по адресу' => [
      'en' => 'The current version of the Policy is freely available on the internet at',
      'ar' => 'النسخة الحالية من السياسة متاحة على الإنترنت على',
    ],
    'ждем вас в гости' => ['en' => 'we look forward to seeing you', 'ar' => 'ننتظر زيارتكم'],
    'заказать обратный звонок' => ['en' => 'request a callback', 'ar' => 'اطلب معاودة الاتصال'],
    'От ст.м. Тушинская рейсовым автобусом №372 или на маршрутном такси. <br>Время в пути 1 час 20 мин до ст. Истра' => [
      'en' => 'From Tushinskaya metro take bus 372 or a minibus.<br>Travel time is 1 hour 20 minutes to Istra station',
      'ar' => 'من مترو توشينسكايا بالحافلة 372 أو الميني باص.<br>مدة الطريق ساعة و20 دقيقة إلى محطة إسترا',
    ],
    'От ст.м. Тушинская рейсовым автобусом №372 или на маршрутном такси.' => [
      'en' => 'From Tushinskaya metro take bus 372 or a minibus.',
      'ar' => 'من مترو توشينسكايا بالحافلة 372 أو الميني باص.',
    ],
    'Время в пути 1 час 20 мин до ст. Истра' => [
      'en' => 'Travel time is 1 hour 20 minutes to Istra station',
      'ar' => 'مدة الطريق ساعة و20 دقيقة إلى محطة إسترا',
    ],
    'Фотогалерея поселка' => ['en' => 'Village photo gallery', 'ar' => 'معرض صور القرية'],
    'Заголовок' => ['en' => 'Category', 'ar' => 'التصنيف'],
    'Пруды' => ['en' => 'Ponds', 'ar' => 'البرك'],
    'Ателье примеры работ' => ['en' => 'Studio work examples', 'ar' => 'أمثلة أعمال المشغل'],
    'Поселок' => ['en' => 'Village', 'ar' => 'القرية'],
    'АРХИТЕКТУРНОЕ<br><span>АТЕЛЬЕ БЭНПАН</span>' => [
      'en' => 'BENPAN<br><span>ARCHITECTURE STUDIO</span>',
      'ar' => 'مشغل بنبان<br><span>المعماري</span>',
    ],
    'АРХИТЕКТУРНОЕ АТЕЛЬЕ БЭНПАН' => ['en' => 'BENPAN ARCHITECTURE STUDIO', 'ar' => 'المشغل المعماري بنبان'],
    'Дом, как отражение индивидуальности, мы создаем пространства, которые говорят за вас' => [
      'en' => 'A house as a reflection of individuality — we create spaces that speak for you',
      'ar' => 'المنزل انعكاس للفردية، نصنع مساحات تتحدث عنكم',
    ],
    'У НАШИХ <br class="br-880">КЛИЕНТОВ <br class="br-desc br-mob"><span>НЕТ НЕОБХОДИМОСТИ<br class="br-880 br-mob"> ИСКАТЬ</span> <br class="br-desc">ОТДЕЛЬНЫХ <br class="br-880 br-mob">ПОДРЯДЧИКОВ' => [
      'en' => 'OUR CLIENTS <br class="br-880">DO NOT NEED <br class="br-desc br-mob"><span>TO LOOK<br class="br-880 br-mob"> FOR</span> <br class="br-desc">SEPARATE <br class="br-880 br-mob">CONTRACTORS',
      'ar' => 'عملاؤنا <br class="br-880">لا يحتاجون <br class="br-desc br-mob"><span>للبحث<br class="br-880 br-mob"> عن</span> <br class="br-desc">مقاولين <br class="br-880 br-mob">منفصلين',
    ],
    'МЫ САМИ РЕШАЕМ ВСЕ ВОПРОСЫ СВЯЗАННЫЕ СО СТРОИТЕЛЬСТвОМ' => [
      'en' => 'WE HANDLE EVERY CONSTRUCTION MATTER OURSELVES',
      'ar' => 'نحن نتولى كل مسائل البناء بأنفسنا',
    ],
    'Архитектурное ателье Бэнпан - это место, где инновационные решения объединяются с мастерством лучших дизайнеров, архитекторов, строителей, создавая идеальные загородные дома, способные впечатлять своим стилем и функциональностью.' => [
      'en' => 'The BENPAN architecture studio is where innovative solutions meet the skill of leading designers, architects and builders, creating country houses that impress with style and function.',
      'ar' => 'مشغل بنبان المعماري مكان تجتمع فيه الحلول المبتكرة ومهارة المصممين والمعماريين والبنائين لصنع منازل ريفية تبهر بالأسلوب والوظيفة.',
    ],
    'Architecture studio Бэнпан - это место, где инновационные решения объединяются с мастерством лучших дизайнеров, архитекторов, строителей, создавая идеальные загородные дома, способные впечатлять своим стилем и функциональностью.' => [
      'en' => 'The BENPAN architecture studio is where innovative solutions meet the skill of leading designers, architects and builders, creating country houses that impress with style and function.',
      'ar' => 'مشغل بنبان المعماري مكان تجتمع فيه الحلول المبتكرة ومهارة المصممين والمعماريين والبنائين لصنع منازل ريفية تبهر بالأسلوب والوظيفة.',
    ],
    'узнать подробнее <br class="br-mob">о гарантиях и условиях' => [
      'en' => 'learn more <br class="br-mob">about warranties and terms',
      'ar' => 'اعرف المزيد <br class="br-mob">عن الضمانات والشروط',
    ],
    'узнать подробнее  о гарантиях и условиях' => [
      'en' => 'learn more about warranties and terms',
      'ar' => 'اعرف المزيد عن الضمانات والشروط',
    ],
    'о гарантиях и условиях' => ['en' => 'about warranties and terms', 'ar' => 'عن الضمانات والشروط'],
    'НАШИ УСЛУГИ' => ['en' => 'OUR SERVICES', 'ar' => 'خدماتنا'],
    'ЭТАПЫ РЕАЛИЗАЦИИ ПРОЕКТА' => ['en' => 'PROJECT STAGES', 'ar' => 'مراحل تنفيذ المشروع'],
    'заказать' => ['en' => 'order', 'ar' => 'اطلب'],
    'ПОЛНЫЙ ЦИКЛ' => ['en' => 'FULL CYCLE', 'ar' => 'دورة كاملة'],
    '«ОТ ПРОЕКТА' => ['en' => '“FROM PROJECT', 'ar' => '«من المشروع'],
    ' ДО РЕАЛИЗАЦИИ»' => ['en' => ' TO DELIVERY”', 'ar' => ' إلى التنفيذ»'],
    'Мы выполняем полный цикл работ "под ключ", который объединяет все задачи - архитектурное проектирование дома, строительные работы, подключение всех инженерных систем, разработка дизайн-проектов и их реализация.' => [
      'en' => 'We deliver a full turnkey cycle: house architecture, construction, all engineering systems, interior design and its implementation.',
      'ar' => 'نقدّم دورة تسليم مفتاح كاملة: تصميم المنزل والبناء وكل الأنظمة الهندسية وتصميم الداخل وتنفيذه.',
    ],
    'Мы выполняем полный цикл работ &quot;под ключ&quot;, который объединяет все задачи - архитектурное проектирование дома, строительные работы, подключение всех инженерных систем, разработка дизайн-проектов и их реализация.' => [
      'en' => 'We deliver a full turnkey cycle: house architecture, construction, all engineering systems, interior design and its implementation.',
      'ar' => 'نقدّم دورة تسليم مفتاح كاملة: تصميم المنزل والبناء وكل الأنظمة الهندسية وتصميم الداخل وتنفيذه.',
    ],
    'Мы выполняем полный цикл работ &quot;под ключ&quot;, который объединяет все задачи - архитектурное проектирование дома, строительные работы, подключение всех инженерных систем, разработка дизайн-projects и их реализация.' => [
      'en' => 'We deliver a full turnkey cycle: house architecture, construction, all engineering systems, interior design and its implementation.',
      'ar' => 'نقدّم دورة تسليم مفتاح كاملة: تصميم المنزل والبناء وكل الأنظمة الهندسية وتصميم الداخل وتنفيذه.',
    ],
    'дизайн-projects' => ['en' => 'design projects', 'ar' => 'مشاريع التصميم'],
    'АРХИТЕКТУРА' => ['en' => 'ARCHITECTURE', 'ar' => 'العمارة'],
    'И ПРОЕКТИРОВАНИЕ' => ['en' => 'AND DESIGN', 'ar' => 'والتصميم'],
    'Индивидуальные проекты для уникальных личностей. Мы создаем не просто здания, а пространства с характером. Эксклюзивные архитектурные решения разработанные нами по индивидуальному проекту, с учетом всех пожеланий и потребности заказчика.' => [
      'en' => 'Custom projects for unique people. We create not just buildings, but spaces with character. Exclusive architecture designed around every wish of the client.',
      'ar' => 'مشاريع فردية لشخصيات فريدة. نصنع لا مجرد مبانٍ بل مساحات ذات طابع، بحلول معمارية خاصة وفق رغبات العميل.',
    ],
    'ДИЗАЙН' => ['en' => 'INTERIOR', 'ar' => 'تصميم'],
    'ИНТЕРЬЕРА' => ['en' => 'DESIGN', 'ar' => 'الداخل'],
    'Разработаем уникальный дизайн-проект интерьера для вашего загородного дома с полным комплектом документации, сметами, визуализациями и чертежами за 45 дней, учитывая ваш бюджет и все пожелания.' => [
      'en' => 'We will create a unique interior design for your country house with a full set of documents, estimates, visuals and drawings in 45 days, within your budget and wishes.',
      'ar' => 'سنعد تصميم داخل فريداً لمنزلكم الريفي مع وثائق وموازنات وتصورات ورسوم خلال 45 يوماً وفق ميزانيتكم ورغباتكم.',
    ],
    'чертежами in 45 days' => ['en' => 'drawings in 45 days', 'ar' => 'رسوم خلال 45 يوماً'],
    'СТРОИТЕЛЬНЫЙ' => ['en' => 'CONSTRUCTION', 'ar' => 'مقاولة'],
    'ПОДРЯД' => ['en' => 'CONTRACT', 'ar' => 'البناء'],
    'Мы осуществляем строительство как часть нашего полного цикла работ "под ключ", что позволяет нам брать на себя ответственность за каждый этап процесса от архитектурного проектирования до финальной отделки.' => [
      'en' => 'We build as part of our turnkey cycle, so we take responsibility for every stage — from architecture to the final finish.',
      'ar' => 'ننفّذ البناء ضمن دورة التسليم المفتاح ونتولى المسؤولية عن كل مرحلة من التصميم إلى التشطيب النهائي.',
    ],
    'Мы осуществляем строительство как часть нашего полного цикла работ &quot;под ключ&quot;, что позволяет нам брать на себя ответственность за каждый этап процесса от архитектурного проектирования до финальной отделки.' => [
      'en' => 'We build as part of our turnkey cycle, so we take responsibility for every stage — from architecture to the final finish.',
      'ar' => 'ننفّذ البناء ضمن دورة التسليم المفتاح ونتولى المسؤولية عن كل مرحلة من التصميم إلى التشطيب النهائي.',
    ],
    'подробнее' => ['en' => 'details', 'ar' => 'المزيد'],
    'Записаться' => ['en' => 'Book', 'ar' => 'احجز'],
    'Разработка архитектурных решений по индивидуальному проекту и уникальных дизайн-проектов интерьера загородного дома с учетом всех пожеланий заказчика' => [
      'en' => 'Custom architectural solutions and unique interior design projects for a country house, tailored to every wish of the client',
      'ar' => 'حلول معمارية خاصة ومشاريع تصميم داخلي فريدة لمنزل ريفي وفق كل رغبات العميل',
    ],
    'Разработка архитектурных решений по индивидуальному проекту и уникальных design projects интерьера загородного дома с учетом всех пожеланий заказчика' => [
      'en' => 'Custom architectural solutions and unique interior design projects for a country house, tailored to every wish of the client',
      'ar' => 'حلول معمارية خاصة ومشاريع تصميم داخلي فريدة لمنزل ريفي وفق كل رغبات العميل',
    ],
    'og:title" content="УК"' => ['en' => 'og:title" content="Management company"', 'ar' => 'og:title" content="شركة الإدارة"'],
    'сервис УК в' => ['en' => 'management service in', 'ar' => 'خدمة الإدارة في'],
    'сервис УК' => ['en' => 'management service', 'ar' => 'خدمة الإدارة'],
    'management service в' => ['en' => 'management service in', 'ar' => 'خدمة الإدارة في'],
    'поможем с обслуживанием дома и территории.' => [
      'en' => 'we will help with the house and grounds.',
      'ar' => 'سنساعد في المنزل والأرض.',
    ],
    'Единая служба для жителей Bereg Pesochnoy:' => [
      'en' => 'A single service for Bereg Pesochnoy residents:',
      'ar' => 'خدمة واحدة لسكان بيريج بيسوتشنايا:',
    ],
    'Единая служба для жителей' => [
      'en' => 'A single service for residents of',
      'ar' => 'خدمة واحدة لسكان',
    ],
    ' в Bereg Pesochnoy' => ['en' => ' in Bereg Pesochnoy', 'ar' => ' في بيريج بيسوتشنايا'],
    'уход за участком, электрика, сантехника и бытовые работы.' => [
      'en' => 'plot care, electrics, plumbing and household work.',
      'ar' => 'عناية بالقطعة وكهرباء وسباكة وأعمال منزلية.',
    ],
    'работаем с эскроу' => ['en' => 'we work with escrow', 'ar' => 'نتعامل مع الإسكرو'],
    'Поможем получить ипотеку от банков партнеров на покупку на дома с участком' => [
      'en' => 'We help you get a mortgage from partner banks for a house with a plot',
      'ar' => 'نساعد في الحصول على رهن من البنوك الشريكة لمنزل مع قطعة',
    ],
    'Забота о доме начинается здесь — сервис УК в Береге Песочной' => [
      'en' => 'Care for the home starts here — management service in Bereg Pesochnoy',
      'ar' => 'العناية بالمنزل تبدأ هنا — خدمة الإدارة في بيريج بيسوتشنايا',
    ],
    'Единая служба для жителей Bereg Pesochnoy: уход за участком, электрика, сантехника и бытовые работы. Оставьте заявку — поможем с обслуживанием дома и территории.' => [
      'en' => 'A single service for Bereg Pesochnoy residents: plot care, electrics, plumbing and household work. Leave a request — we will help with the house and grounds.',
      'ar' => 'خدمة واحدة لسكان بيريج بيسوتشنايا: عناية بالقطعة وكهرباء وسباكة وأعمال منزلية. اتركوا طلباً — سنساعد في المنزل والأرض.',
    ],
    'Единая служба для жителей «Берега Песочной»: уход за участком, электрика, сантехника и бытовые работы. Оставьте заявку — поможем с обслуживанием дома и территории.' => [
      'en' => 'A single service for Bereg Pesochnoy residents: plot care, electrics, plumbing and household work. Leave a request — we will help with the house and grounds.',
      'ar' => 'خدمة واحدة لسكان بيريج بيسوتشنايا: عناية بالقطعة وكهرباء وسباكة وأعمال منزلية. اتركوا طلباً — سنساعد في المنزل والأرض.',
    ],
    'Единая служба для жителей Bereg Pesochnoy: уход за участком, электрика, сантехника и бытовые работы. Leave a request — поможем с обслуживанием дома и территории.' => [
      'en' => 'A single service for Bereg Pesochnoy residents: plot care, electrics, plumbing and household work. Leave a request — we will help with the house and grounds.',
      'ar' => 'خدمة واحدة لسكان بيريج بيسوتشنايا: عناية بالقطعة وكهرباء وسباكة وأعمال منزلية. اتركوا طلباً — سنساعد في المنزل والأرض.',
    ],
    'Поможем получить ипотеку от банков партнеров на покупку на дома с участком в Bereg Pesochnoy, работаем с эскроу' => [
      'en' => 'We help you get a mortgage from partner banks for a house with a plot in Bereg Pesochnoy; we work with escrow',
      'ar' => 'نساعد في الحصول على رهن من البنوك الشريكة لمنزل مع قطعة في بيريج بيسوتشنايا ونتعامل مع الإسكرو',
    ],
    'Поможем получить ипотеку от банков партнеров на покупку на дома с участком в Береге Песочной, работаем с эскроу' => [
      'en' => 'We help you get a mortgage from partner banks for a house with a plot in Bereg Pesochnoy; we work with escrow',
      'ar' => 'نساعد في الحصول على رهن من البنوك الشريكة لمنزل مع قطعة في بيريج بيسوتشنايا ونتعامل مع الإسكرو',
    ],
    'Поможем получить ипотеку от банков партнеров на покупку на дома с участком в «Береге Песочной», работаем с эскроу' => [
      'en' => 'We help you get a mortgage from partner banks for a house with a plot in Bereg Pesochnoy; we work with escrow',
      'ar' => 'نساعد في الحصول على رهن من البنوك الشريكة لمنزل مع قطعة في بيريج بيسوتشنايا ونتعامل مع الإسكرو',
    ],
    '1 этап' => ['en' => 'Stage 1', 'ar' => 'المرحلة 1'],
    '2 этап' => ['en' => 'Stage 2', 'ar' => 'المرحلة 2'],
    '3 этап' => ['en' => 'Stage 3', 'ar' => 'المرحلة 3'],
    '4 этап' => ['en' => 'Stage 4', 'ar' => 'المرحلة 4'],
    '5 этап' => ['en' => 'Stage 5', 'ar' => 'المرحلة 5'],
    '6 этап' => ['en' => 'Stage 6', 'ar' => 'المرحلة 6'],
    '7 этап' => ['en' => 'Stage 7', 'ar' => 'المرحلة 7'],
    'Комплексное изучение территории с целью реализации инженерных изысканий. Обязательный комплекс работ, проводимых на территории будущей застройки. Определяют условия строительства исходя из особенностей местности.' => [
      'en' => 'A full study of the land for engineering surveys. Required work on the future building site. It defines construction conditions from the features of the place.',
      'ar' => 'دراسة شاملة للأرض للمسوحات الهندسية. أعمال إلزامية في موقع البناء المستقبلي تحدد شروط البناء بحسب خصائص المكان.',
    ],
    'Подготовительный процесс к работам на площадке. На этом этапе проводят работы по транспортировке необходимых строительных материалов, техники и оборудования на объект' => [
      'en' => 'Preparing the site. Materials, machinery and equipment are brought to the plot.',
      'ar' => 'تجهيز الموقع. تُنقل المواد والمعدات إلى القطعة.',
    ],
    'Процесс капитального строительства, начиная с фундаментальных работ. Возведение объекта в соответствии с разработанной проектной документацией, в которую входят обязательные земляные работы.' => [
      'en' => 'Capital construction from the foundation. The building is erected to the design documents, including earthworks.',
      'ar' => 'البناء الرأسمالي بدءاً من الأساس وفق الوثائق بما في ذلك أعمال الحفر.',
    ],
    'Монтаж сетей инженерии согласно архитектурно-проектному решению. Создание инфраструктуры объекта. Это заключается в оснащении дома сетями коммуникационными как внешними, так и внутренними.' => [
      'en' => 'Installation of engineering networks to the design. The house is fitted with external and internal utilities.',
      'ar' => 'تركيب الشبكات الهندسية وفق التصميم. تجهيز المنزل بالمرافق الخارجية والداخلية.',
    ],
    'Проведение наружных и внутренних отделочных работ. Комплекс работы, включающий проведение внутренней и внешней отделки здания' => [
      'en' => 'Exterior and interior finishing of the building.',
      'ar' => 'أعمال التشطيب الخارجي والداخلي للمبنى.',
    ],
    'Введение объекта в эксплуатацию. Комплекс работ, предшествующий эксплуатации объекта с целью получения документа, подтверждаю щего проведение строительства в соответствии с проектом' => [
      'en' => 'Commissioning the building and obtaining the document that construction was done to the project.',
      'ar' => 'إدخال المبنى في التشغيل والحصول على وثيقة أن البناء تم وفق المشروع.',
    ],
    'Реализация дизайн-проекта интерьера' => ['en' => 'Implementation of the interior design', 'ar' => 'تنفيذ تصميم الداخل'],
    'Личная встреча для обсуждения деталей проекта, поиск решения и предложений, позволяющих удовлетворить запрос клиента касательно будущего дома.' => [
      'en' => 'A personal meeting to discuss the project and find a solution that meets the client’s request for the future house.',
      'ar' => 'لقاء شخصي لمناقشة تفاصيل المشروع وإيجاد حل يلبي طلب العميل لمنزله المستقبلي.',
    ],
    'Уточнение деталей проекта для составления технического задания. Обсуждение основных моментов, которые позволят приступить к созданию технической документации, отображающей эскиз будущего дома. Разработка дизайн-проекта дома, отражающего главную концепцию объекта.' => [
      'en' => 'Clarifying details for the brief. Discussing the points needed to start the technical documents and a house design that shows the main concept.',
      'ar' => 'توضيح التفاصيل لإعداد المهمة الفنية ووثائق المنزل وتصميم يعكس المفهوم الرئيسي.',
    ],
    'Согласование готового проекта с заказчиком.' => ['en' => 'Approving the finished project with the client.', 'ar' => 'اعتماد المشروع الجاهز مع العميل.'],
    'Составление альбома с проектной документацией и детальным описанием действий.' => [
      'en' => 'Compiling an album of design documents and a detailed description of the work.',
      'ar' => 'إعداد ألبوم الوثائق ووصف مفصّل للأعمال.',
    ],
    'Приемка проекта заказчиком' => ['en' => 'Client acceptance of the project', 'ar' => 'استلام المشروع من العميل'],
    'Консультация с дизайнером и знакомство с архитектурно-строительной студией. Встреча-консультация, по итогам которой будет найдено решение, на основе которого будут определены дальнейшие действия.' => [
      'en' => 'A consultation with the designer and an introduction to the studio. The meeting leads to a solution and the next steps.',
      'ar' => 'استشارة مع المصمم والتعرّف على الاستوديو. اللقاء يفضي إلى حل والخطوات التالية.',
    ],
    'Составление бриф-анкеты на основе пожеланий заказчика с целью создания технического задания. Заказчик в беседе с дизайнером находят решение, максимально отображающее пожелания клиента касательно будущего дома. Будет определен вариант практичного и эстетичного проекта.' => [
      'en' => 'A brief based on the client’s wishes. Together with the designer they find a practical and aesthetic project for the future house.',
      'ar' => 'إعداد موجز وفق رغبات العميل. مع المصمم يُختار مشروع عملي وجمالي للمنزل.',
    ],
    'Планирование и разработка дизайн-проекта на основе ТЗ. На основе решений и пожеланий клиента составляется детальное техническое задание. В него включают оснащение и меблировку интерьера.' => [
      'en' => 'Planning and design from the brief, including interior fittings and furniture.',
      'ar' => 'تخطيط وتصميم وفق المهمة الفنية بما في ذلك التجهيز والأثاث.',
    ],
    'Разработка дизайн-проекта ,составление проектных решений объекта недвижимости, чертежей, 3D визуализаций помещений, составление спецификации материалов.' => [
      'en' => 'Design development: drawings, 3D visuals of the rooms and a materials specification.',
      'ar' => 'تطوير التصميم: رسوم وتصورات ثلاثية الأبعاد ومواصفات المواد.',
    ],
    'Реализация проекта согласно документации под авторским надзором. Когда визуальная проекция и практический пакет документов собран, приступают к реализации. Авторский надзор обеспечит детальное следование все решениям, согласно плану' => [
      'en' => 'Implementation to the documents under author’s supervision, so every decision is followed as planned.',
      'ar' => 'التنفيذ وفق الوثائق بإشراف المؤلف لضمان اتباع كل القرارات.',
    ],
    'Осуществление обязательных инженерных изысканий.' => ['en' => 'Mandatory engineering surveys.', 'ar' => 'المسوحات الهندسية الإلزامية.'],
    'Этап включает проведение комплекса проектных работ с целью определения особенностей участка, изучения климатических условий зоны, грунта, подземных вод и иных природных характеристик.' => [
      'en' => 'This stage studies the plot, climate, soil, groundwater and other natural features.',
      'ar' => 'تدرس هذه المرحلة القطعة والمناخ والتربة والمياه الجوفية وخصائص طبيعية أخرى.',
    ],
    'Подготовительные работы' => ['en' => 'Preparatory work', 'ar' => 'أعمال تحضيرية'],
    'Данный этап включает транспортировку конструкций дома к месту строительства, работы по подготовке территории к устройству фундамента, подсоединение к инженерно-техническим сетям обеспечения' => [
      'en' => 'House structures are brought to the site, the land is prepared for the foundation, and utilities are connected.',
      'ar' => 'تُنقل هياكل المنزل إلى الموقع وتُجهَّز الأرض للأساس وتُوصل المرافق.',
    ],
    'Осуществление капитального строительства.' => ['en' => 'Capital construction.', 'ar' => 'البناء الرأسمالي.'],
    'На этом этапе возводится фундамент, стены дома, межэтажные перекрытия, производятся кровельные работы.' => [
      'en' => 'The foundation, walls, floors and roof are built at this stage.',
      'ar' => 'في هذه المرحلة يُبنى الأساس والجدران والأسقف والسقف.',
    ],
    'Монтаж инженерных сетей.' => ['en' => 'Installation of engineering networks.', 'ar' => 'تركيب الشبكات الهندسية.'],
    'Установка систем инженерии, согласно архитектурному решению. Подключение внешних и внутренних коммуникаций согласно проекту.' => [
      'en' => 'Engineering systems are installed to the design. External and internal utilities are connected.',
      'ar' => 'تُركَّب الأنظمة وفق التصميم وتُوصل المرافق الخارجية والداخلية.',
    ],
    'Ремонтно-отделочные работы.' => ['en' => 'Finishing works.', 'ar' => 'أعمال التشطيب.'],
    'Проведение черновых и чистовых ремонтно-отделочных работ с целью благоустройства дома.' => [
      'en' => 'Rough and finish works to complete the house.',
      'ar' => 'أعمال تشطيب خشنة ونهائية لتجهيز المنزل.',
    ],
    'Проведение ландшафтных работ.' => ['en' => 'Landscape works.', 'ar' => 'أعمال تنسيق الأرض.'],
    'Финальный комплекс работ, благодаря которому проект получает окончательный внешний вид. Придомовую территорию облагораживают и благоустраивают.' => [
      'en' => 'The final works that give the project its finished look. The grounds around the house are landscaped.',
      'ar' => 'الأعمال النهائية التي تمنح المشروع مظهره. تُنسَّق الأرض حول المنزل.',
    ],
    'Введение дома в эксплуатацию.' => ['en' => 'Commissioning the house.', 'ar' => 'إدخال المنزل في التشغيل.'],
    'Получение документа, свидетельствующего о том, что строительные работы были проведены в срок и в соответствии с проектом.' => [
      'en' => 'Receiving the document that construction was completed on time and to the project.',
      'ar' => 'الحصول على وثيقة أن البناء أُنجز في الموعد ووفق المشروع.',
    ],
    'ПРЕИМУЩЕСТВА' => ['en' => 'ADVANTAGES', 'ar' => 'المزايا'],
    'РАБОТЫ С НАМИ' => ['en' => 'OF WORKING WITH US', 'ar' => 'من العمل معنا'],
    'ЭКОНОМИЯ БЮДЖЕТА' => ['en' => 'BUDGET SAVINGS', 'ar' => 'توفير الميزانية'],
    'Заказывая у нас, вы можете быть уверены в том, что просчитанная заранее смета проекта будет соблюдена и вы получите готовое решение, контролируемое на каждом из этапов' => [
      'en' => 'When you order with us, the estimate is kept and you get a finished solution controlled at every stage',
      'ar' => 'عند الطلب معنا تُحترم الموازنة المحسوبة مسبقاً وتحصلون على حل جاهز يُراقب في كل مرحلة',
    ],
    'ИНДИВИДУАЛЬНЫЙ ПОДХОД' => ['en' => 'A PERSONAL APPROACH', 'ar' => 'نهج فردي'],
    'Учитываем все пожелания и потребности, отражающие вашу индивидуальность.' => [
      'en' => 'We take into account every wish that reflects your individuality.',
      'ar' => 'نراعي كل الرغبات التي تعكس فرديتكم.',
    ],
    'ПРОФЕССИОНАЛЬНАЯ КОМАНДА' => ['en' => 'A PROFESSIONAL TEAM', 'ar' => 'فريق محترف'],
    'Высококвалифицированные архитекторы и дизайнеры с большим опытом в проектировании частных домов, следящие за мировыми тенденциями в дизайне, помогут реализовать ваши идеи на высшем уровне.' => [
      'en' => 'Experienced architects and designers who follow world design trends will bring your ideas to a high level.',
      'ar' => 'معماريون ومصممون ذوو خبرة يتابعون الاتجاهات العالمية سيحققون أفكاركم بمستوى عالٍ.',
    ],
    'КОНТРОЛЬ КАЧЕСТВА' => ['en' => 'QUALITY CONTROL', 'ar' => 'ضبط الجودة'],
    'Наша компания осуществляет авторский и строительный надзор. Тем самым вся ответственность за результат выполненных работ лежит на нас. Мы контролируем каждый из этапов, а вы можете быть уверены в результате' => [
      'en' => 'We provide author’s and construction supervision. Responsibility for the result is ours. We control every stage so you can be sure of the outcome.',
      'ar' => 'نقوم بإشراف المؤلف والبناء. المسؤولية عن النتيجة علينا. نراقب كل مرحلة لتطمئنوا إلى الناتج.',
    ],
    'Выбор участков с подрядом' => ['en' => 'Plots with construction', 'ar' => 'قطع مع البناء'],
    'Выбор участков with construction' => ['en' => 'Plots with construction', 'ar' => 'قطع مع البناء'],
    'Выберите любой свободный понравившийся участок' => [
      'en' => 'Choose any available plot you like',
      'ar' => 'اختاروا أي قطعة متاحة تعجبكم',
    ],
    'Мечтаете о своем доме, но боитесь, что стройка затянется на годы, а бюджет вырастет в два раза?' => [
      'en' => 'Dream of your own house but fear the build will drag on for years and the budget will double?',
      'ar' => 'تحلمون بمنزلكم وتخافون أن تطول البناء سنوات وأن تتضاعف الميزانية؟',
    ],
    'Тогда формат «Участок + Подряд» — это ваш идеальный старт!' => [
      'en' => 'Then the “Plot + Build” format is your ideal start!',
      'ar' => 'إذن صيغة «قطعة + بناء» هي انطلاقتكم المثالية!',
    ],
    'Тогда формат «Plot + Подряд» — это ваш идеальный старт!' => [
      'en' => 'Then the “Plot + Build” format is your ideal start!',
      'ar' => 'إذن صيغة «قطعة + بناء» هي انطلاقتكم المثالية!',
    ],
    'Осталось всего 5 участков с готовыми проектными решениями!' => [
      'en' => 'Only 5 plots with ready design solutions are left!',
      'ar' => 'تبقّت 5 قطع فقط بحلول تصميم جاهزة!',
    ],
    'Как мы работаем:' => ['en' => 'How we work:', 'ar' => 'كيف نعمل:'],
    'Вы выбираете понравившийся участок на карте поселка.' => [
      'en' => 'You choose a plot you like on the village map.',
      'ar' => 'تختارون قطعة تعجبكم على خريطة القرية.',
    ],
    'Выбираете типовой или адаптируете индивидуальный проект дома.' => [
      'en' => 'You pick a typical house project or adapt a custom one.',
      'ar' => 'تختارون مشروعاً نمطياً أو تكيّفون تصميماً خاصاً.',
    ],
    'Мы заключаем единый договор.' => ['en' => 'We sign a single contract.', 'ar' => 'نبرم عقداً واحداً.'],
    'Через 35 дней вы принимаете готовый дом и получаете ключи.' => [
      'en' => 'In 35 days you accept the finished house and get the keys.',
      'ar' => 'خلال 35 يوماً تستلمون المنزل الجاهز والمفاتيح.',
