    'Запишитесь на экскурсию по поселку и посмотрите на реализованные объекты лично!' => [
      'en' => 'Book a village tour and see completed homes in person!',
      'ar' => 'احجزوا جولة في القرية وشاهدوا المنازل المنفّذة بأنفسكم!',
    ],
    'Запишитесь a tour по поселку и посмотрите на реализованные объекты лично!' => [
      'en' => 'Book a village tour and see completed homes in person!',
