    'скачать каталог отделки' => ['en' => 'download the finish catalog', 'ar' => 'حمّلوا كتالوج التشطيب'],
    '3 ГОТОВЫХ ВАРИАНТА ОТДЕЛКИ' => ['en' => '3 READY FINISH OPTIONS', 'ar' => '3 خيارات تشطيب جاهزة'],
    'заказать проект<br>в своем стиле' => ['en' => 'order a project<br>in your style', 'ar' => 'اطلبوا مشروعاً<br>بأسلوبكم'],
    'заказать проект в своем стиле' => ['en' => 'order a project in your style', 'ar' => 'اطلبوا مشروعاً بأسلوبكم'],
    'EcoSmart – это микс стилей, объединяющий лучшие черты современного, скандинавского, хай-тека и эко-стиля. Он создан для тех, кто ценит функциональность, природную эстетику и технологичный комфорт.' => [
      'en' => 'EcoSmart is a mix of modern, Scandinavian, hi-tech and eco styles. It is for those who value function, natural aesthetics and technical comfort.',
      'ar' => 'إيكو سمارت مزيج من الحديث والإسكندنافي والهاي تك والإيكو. لمن يقدّر الوظيفة والجمال الطبيعي والراحة التقنية.',
    ],
    'Eterna – стиль, который олицетворяет вечность и неизменную элегантность. Название происходит от латинского слова «вечный», и отражает стремление создать пространство, которое не потеряет своей актуальности с течением времени. В интерьерах в стиле Eterna сочетаются классические элементы с современными акцентами, создавая гармонию между традицией и современностью' => [
      'en' => 'Eterna stands for lasting elegance. The name comes from the Latin for “eternal”. Classic elements meet modern accents, keeping the space relevant over time.',
      'ar' => 'إيتيرنا أسلوب الأناقة الدائمة من اللاتينية «أبدي». يجمع عناصر كلاسيكية ولمسات حديثة ليبقى المكان راهناً مع الزمن.',
    ],
    'Serenita - от итальянского “serenità”, что переводится как спокойствие или безмятежность. Основной идей стиля является создание пространства, которое наполняет гармонией и умиротворением. Это авторский стиль, объединяющий элементы минимализма, джапанди и контемпорари. Он фокусируется на внутреннем комфорте, эстетической чистоте и функциональности, идеально подходя для современных домов, где ценится простота и природная красота.' => [
      'en' => 'Serenita comes from Italian “serenità” — calm. It mixes minimalism, japandi and contemporary, focusing on comfort, visual clarity and function for homes that value simplicity and nature.',
      'ar' => 'سيرينيتا من الإيطالية «صفاء». تمزج المينيمال والجاباندي والمعاصر وتركّز على الراحة والنقاء البصري والوظيفة.',
    ],
    'ЗАКАЗАТЬ ИНТЕРЬЕР В ЭТОМ СТИЛЕ' => ['en' => 'ORDER AN INTERIOR IN THIS STYLE', 'ar' => 'اطلبوا داخلاً بهذا الأسلوب'],
    'ДАЕМ ГАРАНТИЮ' => ['en' => 'WE GUARANTEE', 'ar' => 'نضمن'],
