    ],
    'ЛЕТ РАЗРАБАТЫВАЕМ<br>ДИЗАЙН ПРОЕКТЫ' => ['en' => 'YEARS OF DESIGN<br>PROJECTS', 'ar' => 'سنوات من<br>مشاريع التصميم'],
