    'Забота о доме начинается здесь' => ['en' => 'Care for the home starts here', 'ar' => 'العناية بالمنزل تبدأ هنا'],
    'Единая служба для решения бытовых и технических задач жителей «Берега Песочной» — от ухода за участком до электромонтажных и сантехнических работ.' => [
