    'our specialists will advise you and select the best financing for a house or a plot' => [
      'en' => 'our specialists will advise you and select the best financing for a house or a plot',
      'ar' => 'سيقدم لكم المختصون أفضل تمويل لمنزل أو قطعة',
    ],
    'наши специалисты проконсультируют вас и подберут лучшее финансирование для дома или участка' => [
      'en' => 'our specialists will advise you and select the best financing for a house or a plot',
      'ar' => 'سيقدم لكم المختصون أفضل تمويل لمنزل أو قطعة',
    ],
    'Эскроу-счет' => ['en' => 'Escrow account', 'ar' => 'حساب إسكرو'],
    'высокий процент одобрения заявок <br>банком' => [
      'en' => 'high bank approval<br>rate',
      'ar' => 'نسبة موافقة<br>عالية من البنك',
    ],
    'Свой загородный дом на небольшом участке земли — мечта большинства городских жителей. Всем нам хочется, чтобы она исполнилась как можно скорее. Предлагаем популярный способ быстро реализовать мечту, купить в ипотеку дом с участком в коттеджном поселке «Берег Песочной» в ближнем Подмосковье. Ипотека на покупку загородного дома в Московской области — это возможность быстро купить готовую дачу под ключ с участком или таунхаус у воды в Истринском районе.' => [
      'en' => 'A country house on a modest plot is a dream for most city dwellers. We offer a popular way to make it real sooner: buy a house with a plot in Bereg Pesochnoy with a mortgage. A Moscow-Region mortgage lets you quickly buy a turnkey dacha with land or a townhouse by the water in the Istra district.',
      'ar' => 'منزل ريفي على قطعة صغيرة حلم لكثير من سكان المدينة. نقدّم طريقة شائعة لتحقيقه أسرع: شراء منزل مع قطعة في بيريج بيسوتشنايا برهن. رهن ضواحي موسكو يتيح شراء داشا جاهزة أو تاون هاوس على الماء في منطقة إسترا.',
    ],
    'почему стоит <br><span>оформить ипотеку</span>' => [
      'en' => 'why you should <br><span>get a mortgage</span>',
      'ar' => 'لماذا يستحق <br><span>الرهن</span>',
    ],
    'почему стоит' => ['en' => 'why you should', 'ar' => 'لماذا يستحق'],
    'оформить ипотеку' => ['en' => 'get a mortgage', 'ar' => 'الحصول على رهن'],
    'льготная ипотека' => ['en' => 'preferential mortgage', 'ar' => 'رهن ميسر'],
    'Ставка 6-11%;<br> - увеличенный лимит до 30 млн;<br> - материнский капитал в первоначальный взнос;<br> -расчеты через счет эскроу.' => [
      'en' => 'Rate 6–11%;<br> - a higher limit up to 30 million;<br> - maternity capital as the down payment;<br> - settlements via escrow.',
      'ar' => 'نسبة 6–11٪؛<br> - حد أعلى حتى 30 مليوناً؛<br> - رأس مال الأمومة كدفعة أولى؛<br> - تسويات عبر إسكرو.',
    ],
    'ООО БЭНСТРОЙ генеральный подрядчик КП "Берег Песочной" аккредитован в ведущих банках ДОМ.рф, Сбербанк, ВТБ, Альфабанк, Газпромбанк.' => [
      'en' => 'BENSTROY LLC, general contractor of Bereg Pesochnoy, is accredited with DOM.RF, Sberbank, VTB, Alfa-Bank and Gazprombank.',
      'ar' => 'شركة بنستروي المقاول العام لبيريج بيسوتشنايا معتمدة لدى DOM.RF وسبيربنك وفي تي بي وألفا بنك وغازبروم بنك.',
    ],
    'быстро, выгодно <br>и удобно' => ['en' => 'fast, profitable <br>and convenient', 'ar' => 'سريع ومفيد <br>ومريح'],
    'Не надо копить всю сумму целиком, можно быстро построиться и жить в собственном доме заплатив небольшой первоначальный взнос, равномерно и предсказуемо оплачивать кредит необременительными суммами. Покупка участка и строительство дома в одной ипотечной сделке.' => [
      'en' => 'You do not need the full sum at once. Pay a modest down payment, live in your own house and repay the loan in even, predictable amounts. The plot and the house are in one mortgage deal.',
      'ar' => 'لا حاجة لكامل المبلغ دفعة واحدة. دفعة أولى صغيرة ثم سداد متساوٍ متوقع. القطعة وبناء المنزل في صفقة رهن واحدة.',
    ],
    'оплачивать loan' => ['en' => 'repay the loan', 'ar' => 'سداد القرض'],
    'Purchase участка' => ['en' => 'Purchase of the plot', 'ar' => 'شراء القطعة'],
    'помогаем решить <br>сложные ситуации' => ['en' => 'we help with <br>complex cases', 'ar' => 'نساعد في <br>الحالات المعقّدة'],
    'Окажем помощь в получении кредита, работаем с любыми ипотечными программами (IT-ипотека, Семейная, стандартная) рассчитанными на строительство индивидуальных домов.' => [
      'en' => 'We help you get a loan and work with any mortgage programmes (IT, Family, standard) for individual house construction.',
      'ar' => 'نساعد في الحصول على القرض ونتعامل مع برامج الرهن (IT والعائلية والقياسية) لبناء المنازل الفردية.',
    ],
    'IT mortgage' => ['en' => 'IT mortgage', 'ar' => 'رهن IT'],
    'нас часто<br>спрашивают' => ['en' => 'people often<br>ask us', 'ar' => 'يسألوننا<br>كثيراً'],
    'какие требования к заемщику?' => ['en' => 'what are the borrower requirements?', 'ar' => 'ما متطلبات المقترض؟'],
    'Требования к заемщику:' => ['en' => 'Borrower requirements:', 'ar' => 'متطلبات المقترض:'],
    'паспорт гражданина РФ.' => ['en' => 'a Russian passport.', 'ar' => 'جواز روسي.'],
    'возраст от 21 года до 65 лет' => ['en' => 'age from 21 to 65', 'ar' => 'العمر من 21 إلى 65'],
    'стаж не менее 3 месяцев.' => ['en' => 'at least 3 months of employment.', 'ar' => 'خبرة لا تقل عن 3 أشهر.'],
    'Для семейной ипотеки:' => ['en' => 'For the family mortgage:', 'ar' => 'للرهن العائلي:'],
    'Семья с ребенком в возрасте до 6 лет' => ['en' => 'A family with a child under 6', 'ar' => 'أسرة بطفل دون 6 سنوات'],
    'Семья с двумя и более детьми до 18 лет' => ['en' => 'A family with two or more children under 18', 'ar' => 'أسرة بطفلين أو أكثر دون 18'],
    'Семья с ребенком с инвалидностью до 18 лет' => ['en' => 'A family with a child with a disability under 18', 'ar' => 'أسرة بطفل ذي إعاقة دون 18'],
    'Для IT-специалистов:' => ['en' => 'For IT specialists:', 'ar' => 'لمختصي IT:'],
    'IT-компания получила аккредитацию Минцифры РФ;' => [
      'en' => 'the IT company is accredited by the Russian Ministry of Digital Development;',
      'ar' => 'شركة IT معتمدة من وزارة التحول الرقمي الروسية؛',
