    'может ли пара в гражданском браке получить кредит?' => [
      'en' => 'can an unmarried couple get a loan?',
      'ar' => 'هل يمكن لزوجين غير رسميين الحصول على قرض؟',
    ],
    'Взять ипотеку не будучи в официальном браке, можно. Оформить ее нужно в долевую собственность — и лучше выделить одинаковые доли. Оба партнера будут равноправными созаемщиками по ипотечному договору.' => [
      'en' => 'Yes, without a registered marriage. Arrange shared ownership — equal shares are better. Both partners become equal co-borrowers.',
      'ar' => 'نعم دون زواج رسمي. يُفضَّل ملكية مشتركة بحصص متساوية. الشريكان مقترضان متساويان.',
    ],
    'как увеличить шансы на получение ипотеки в IZHS?' => [
