    'Привлечь поручителя или созаемщик' => ['en' => 'Bring a guarantor or a co-borrower', 'ar' => 'استعينوا بكفيل أو مقترض مشارك'],
    'можно ли привлечь созаемщиков для получения кредита?' => [
