    'Индивидуальный проект жилого дома ПБ-134 общей площадью 132,4 м2. Данный коттедж с вальмовой кровлей выполнен из панелей БЭНПАН Премиум и Апекс, предназначен для комфортного проживания 5-6 человек.' => [
      'en' => 'A custom PB-134 house of 132.4 m². This cottage with a hipped roof is built from BENPAN Premium and Apex panels and is designed for 5–6 people.',
      'ar' => 'مشروع فردي للمنزل PB-134 بمساحة 132.4 م². الكوخ بسقف وركي من ألواح بنبان بريميوم وأبيكس، مخصص لإقامة مريحة لـ 5–6 أشخاص.',
    ],
    'Дом двухэтажный. На первом этаже располагаются: тамбур, санузел, котельная, просторная кухня-гостиная с открытой лестницей, спальня с отдельным санузлом. На втором этаже уютно разместились 3 спальни, одна из которых мастер-спальня, санузел и кладовая.' => [
      'en' => 'A two-storey house. The first floor has an entrance hall, a bathroom, a boiler room, a spacious kitchen-living room with an open stair, and a bedroom with its own bathroom. The second floor has 3 bedrooms, including a master bedroom, a bathroom and a pantry.',
      'ar' => 'منزل من طابقين. في الطابق الأول: دهليز وحمّام وغرفة غلاية ومطبخ-معيشة فسيح بدرج مفتوح وغرفة نوم بحمّام خاص. في الطابق الثاني 3 غرف نوم منها الرئيسية وحمّام ومخزن.',
    ],
