    'ДВЕРЬ<br class="cart-mob-br2"> С ТЕРМОРАЗРЫВОМ' => ['en' => 'DOOR<br class="cart-mob-br2"> WITH THERMAL BREAK', 'ar' => 'باب<br class="cart-mob-br2"> بعازل حراري'],
    'МЕТ. КАРКАС<br class="cart-mob-br2"> ЛЕСТНИЦЫ' => ['en' => 'METAL STAIR<br class="cart-mob-br2"> FRAME', 'ar' => 'هيكل معدني<br class="cart-mob-br2"> للدرج'],
    'ЗАВЕДЕНА<br class="cart-mob-br2"> КАНАЛИЗАЦИЯ' => ['en' => 'SEWAGE<br class="cart-mob-br2"> CONNECTED', 'ar' => 'صرف<br class="cart-mob-br2"> موصل'],
