    'ГАЗ ПО ГРАНИЦЕ<br class="cart-mob-br2"> УЧАСТКА' => ['en' => 'GAS AT THE<br class="cart-mob-br2"> PLOT BOUNDARY', 'ar' => 'غاز على<br class="cart-mob-br2"> حدود القطعة'],
