    'Описание' => ['en' => 'Description', 'ar' => 'الوصف'],
    'Мы строим по <br>технологии <span>Бэнпан</span>' => [
      'en' => 'We build with <br>the <span>BENPAN</span> technology',
      'ar' => 'نبني بتقنية <br><span>بنبان</span>',
    ],
    'Стеновые панели БЭНПАН Премиум' => ['en' => 'BENPAN Premium wall panels', 'ar' => 'ألواح بنبان بريميوم الجدارية'],
    'Железобетонная стеновая панель БЭНПАН Премиум имеет трехслойную конструкцию, состоящую из наружного слоя фибробетона класса В30 толщиной 50 мм, внутреннего теплоизоляционного слоя толщиной 170 мм и внутреннего слоя фибробетона класса В20 толщиной 50-140 мм (в ребре). Помимо пенополистирола возможна установка в качестве утеплителя экструзионного пенополистирола или PIR-панелей.' => [
      'en' => 'The BENPAN Premium reinforced-concrete wall panel has a three-layer build: an outer 50 mm B30 fibre-concrete layer, a 170 mm insulation layer, and an inner B20 fibre-concrete layer 50–140 mm thick in the rib. XPS or PIR panels can be used instead of EPS.',
      'ar' => 'لوح بنبان بريميوم الخرساني ثلاثي الطبقات: طبقة خارجية من فيبر كونكريت ب30 سماكة 50 مم، عزل 170 مم، وطبقة داخلية ب20 سماكة 50–140 مم في الضلع. يمكن استخدام XPS أو PIR بدل البوليسترين.',
    ],
    'Размер и форма железобетонной стеновой панели БЭНПАН Премиум, а также наличие оконных и дверных проемов определяются проектом. Максимальная высота панели может достигать 3,05 метра, а длина — 7 метров' => [
      'en' => 'The size and shape of the BENPAN Premium panel, and the window and door openings, are set by the project. Maximum panel height is 3.05 m and length is 7 m',
      'ar' => 'حجم وشكل لوح بنبان بريميوم وفتحات النوافذ والأبواب يحددها المشروع. أقصى ارتفاع 3.05 م والطول 7 م',
    ],
    'Внешняя сторона панелей может быть<br> гладкой или с отделкой фасада:' => [
      'en' => 'The outer face of the panels can be<br> smooth or with a facade finish:',
      'ar' => 'الوجه الخارجي للألواح يمكن أن يكون<br> أملس أو بتشطيب واجهة:',
    ],
    'дикий камень' => ['en' => 'wild stone', 'ar' => 'حجر طبيعي'],
    'Цельнолитая панель с рельефом дикого камня – надежное решение для фасада которое придаст вашему дому неповторимый вид.' => [
      'en' => 'A cast panel with a wild-stone relief — a reliable facade that gives the house a unique look.',
      'ar' => 'لوح مصبوب بنقش الحجر الطبيعي — حل موثوق للواجهة يمنح المنزل مظهراً فريداً.',
    ],
    'Клинкер' => ['en' => 'Clinker', 'ar' => 'كلينكر'],
    'Облицовка фасада клинкерной плиткой ― эффективное решение для отделки стеновых конструкций. Гарантирует надежность и уникальный вид дома.' => [
      'en' => 'Clinker tile cladding is an effective wall finish. It is durable and gives the house a unique look.',
      'ar' => 'كسوة الواجهة ببلاط الكلينكر حل فعّال لتشطيب الجدران ويضمن المتانة ومظهراً فريداً.',
    ],
    'штукатурка' => ['en' => 'plaster', 'ar' => 'لياسة'],
    'Фасадная декоративная штукатурка Сeresit, гарантирует надежную стойкость покрытия в течении долгого времени и придает поверхности изысканный и привлекательный вид.' => [
      'en' => 'Ceresit decorative facade plaster keeps its look for a long time and gives the surface an elegant finish.',
      'ar' => 'لياسة Ceresit الزخرفية للواجهة تدوم طويلاً وتمنح السطح مظهراً أنيقاً.',
    ],
    'Фасадная декоративная plaster Сeresit, гарантирует надежную стойкость покрытия в течении долгого времени и придает поверхности изысканный и привлекательный вид.' => [
      'en' => 'Ceresit decorative facade plaster keeps its look for a long time and gives the surface an elegant finish.',
      'ar' => 'لياسة Ceresit الزخرفية للواجهة تدوم طويلاً وتمنح السطح مظهراً أنيقاً.',
    ],
    'Фасадная декоративная plaster Сeresit, гарантирует надежную стойкость покрытия в течении долгого времени и  придает поверхности изысканный и привлекательный вид.' => [
      'en' => 'Ceresit decorative facade plaster keeps its look for a long time and gives the surface an elegant finish.',
      'ar' => 'لياسة Ceresit الزخرفية للواجهة تدوم طويلاً وتمنح السطح مظهراً أنيقاً.',
    ],
    'Фасадная декоративная plaster Сeresit, гарантирует надежную стойкость покрытия в течении долгого времени и  придает поверхности изысканный и привлекательный вид.  ' => [
      'en' => 'Ceresit decorative facade plaster keeps its look for a long time and gives the surface an elegant finish.',
