    'черновая отделка' => ['en' => 'rough finishing', 'ar' => 'تشطيب خشن'],
    'черновая finishing' => ['en' => 'rough finishing', 'ar' => 'تشطيب خشن'],
    'Подготовка всех поверхностей в помещении для следующего финишного оформления' => [
      'en' => 'Preparing all indoor surfaces for the next finish',
      'ar' => 'تجهيز كل الأسطح الداخلية للتشطيب التالي',
    ],
    'Индивидуальное проектирование, уникальные решения и профессиональное сопровождение на каждом этапе работ' => [
      'en' => 'Custom design, unique solutions and professional support at every stage',
      'ar' => 'تصميم فردي وحلول فريدة ومتابعة محترفة في كل مرحلة',
    ],
    'Устройство систем электроснабжения, водоснабжения, канализации, отопления, монтаж батарей, установка подоконников. Штукатурка стен с фасадной сеткой.' => [
      'en' => 'Power, water, sewage and heating systems, radiator installation, window sills. Wall plaster with facade mesh.',
      'ar' => 'أنظمة الكهرباء والماء والصرف والتدفئة وتركيب المشعات وعتبات النوافذ. لياسة الجدران مع شبكة الواجهة.',
    ],
    'Архитектурное ателье Бэнпан предлагает профессиональные услуги по индивидуальному проектированию интерьеров частных малоэтажных домов и благоустройству придомовых территорий. Команда архитекторов и дизайнеров с большим опытом работы разработает уникальный проект интерьера, поможет приобрести и правильно расставить мебель в соответствии с вашими пожеланиями и учетом современных трендов в архитектуре и дизайне.' => [
      'en' => 'The BENPAN architecture studio designs interiors for private low-rise houses and landscaping. Experienced architects and designers will create a unique interior, help you buy furniture and place it to your wishes and current trends.',
      'ar' => 'مشغل بنبان المعماري يصمم دواخل المنازل الخاصة وتنسيق الأرض. فريق من المعماريين والمصممين يعد مشروعاً فريداً ويساعد في شراء الأثاث وترتيبه وفق رغباتكم والاتجاهات الحديثة.',
    ],
    'Architecture studio Бэнпан предлагает профессиональные услуги по индивидуальному проектированию интерьеров частных малоэтажных домов и благоустройству придомовых территорий. Команда архитекторов и дизайнеров с большим опытом работы разработает уникальный проект интерьера, поможет приобрести и правильно расставить мебель в соответствии с вашими пожеланиями и учетом современных трендов в архитектуре и дизайне.' => [
      'en' => 'The BENPAN architecture studio designs interiors for private low-rise houses and landscaping. Experienced architects and designers will create a unique interior, help you buy furniture and place it to your wishes and current trends.',
      'ar' => 'مشغل بنبان المعماري يصمم دواخل المنازل الخاصة وتنسيق الأرض. فريق من المعماريين والمصممين يعد مشروعاً فريداً ويساعد في شراء الأثاث وترتيبه وفق رغباتكم والاتجاهات الحديثة.',
    ],
