    'ЧЕМ ЗАНЯТЬСЯ' => ['en' => 'WHAT TO DO', 'ar' => 'ماذا تفعلون'],
    'гимнастическая площадка' => ['en' => 'gymnastics area', 'ar' => 'ساحة جمباز'],
    'Все для спорта и активного отдыха. Комплекс для занятия уличной гимнастикой (воркаут), волейбольная площадка, столы для настольного тенниса.' => [
      'en' => 'Everything for sport and outdoor leisure. A street gymnastics (workout) area, a volleyball court and table-tennis tables.',
      'ar' => 'كل شيء للرياضة والراحة. مجمع جمباز خارجي وملعب كرة طائرة وطاولات تنس طاولة.',
    ],
    'All для спорта и активного отдыха. Комплекс для занятия уличной гимнастикой (воркаут), волейбольная площадка, столы для настольного тенниса.' => [
      'en' => 'Everything for sport and outdoor leisure. A street gymnastics (workout) area, a volleyball court and table-tennis tables.',
